/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"물류의 정의와 변천","줄":[{"t":"물류(물류정책기본법): 재화가 공급자로부터 조달·생산되어 수요자에게 전달되거나 소비자로부터 회수되어 폐기될 때까지 이루어지는 운송·보관·하역 등과 이에 부가되어 가치를 창출하는 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등","src":"물류정책기본법 제2조 제1항 제1호"},{"t":"물적유통(Physical Distribution): 판매영역 중심의 물자 흐름","src":"기출 2022-21, 2024-1"},{"t":"쇼(A.W. Shaw): 경영활동 내 유통의 한 영역으로 Physical Distribution 개념을 정의","src":"기출 2022-21"},{"t":"물적유통은 주로 수송·보관·하역·포장 등 부문별 효율화를 추구","src":"기출 2025-3"},{"t":"로지스틱스(Logistics): 병참(군사용어)에서 유래, 조달·생산·판매·회수물류를 포함하는 총체적 개념","src":"기출 2024-1, 2026-1"},{"t":"로지스틱스는 조달·생산·판매 등 기업 내 물류 효율화가 목표. 재화가 조달·생산되어 소비자에게 전달되고 폐기되는 과정까지 포함","src":"기출 2025-3, 2022-21"},{"t":"물류와 Logistics는 혼용되나 범위는 Logistics가 더 넓다","src":"기출 2023-11"},{"t":"SCM(공급사슬관리): 공급자·제조업자·도소매점·고객 등 공급사슬 전반의 효율화가 목적. 고객·공급업체·제조업체·유통업체 네트워크의 재화·정보·자금 흐름을 다룸","src":"기출 2025-3, 2024-1"},{"t":"범위 확대 순서: 물적유통 → 로지스틱스 → SCM. 2000년대부터 SCM으로 변천","src":"기출 2025-3, 2023-11"},{"t":"전통적 물류 개념: 사물의 흐름과 관련된 시간적·공간적 효용을 창출하는 경영활동","src":"기출 2023-11"},{"t":"물류시스템: 생산과 소비를 연결하며 공간적·시간적 효용을 창출","src":"기출 2022-1"},{"t":"물류의 목적: 물류서비스 증대와 물류비용 최소화","src":"기출 2022-1"},{"t":"물류시스템 자원: 인적·물적·재무적·정보적 자원","src":"기출 2022-1"},{"t":"물류하부시스템: 수송·보관·포장·하역·물류정보·유통가공","src":"기출 2022-1"}]},{"머리":"물류 3S 1L과 7R","줄":[{"t":"3S 1L 원칙: 신속성(Speedy)·안정성(Safely)·확실성(Surely)·경제성(Low)","src":"기출 2024-1"},{"t":"스마이키(E.W. Smykey)의 7R: 적절한 상품(Commodity)·품질(Quality)·수량(Quantity)·시간(Time)·장소(Place)·가격(Price)·인상(Impression)","src":"기출 2021-5, 2023-2, 2024-1, 2026-5"},{"t":"7R에 해당하지 않는 것으로 출제된 것: 적절한 고객(Customer), 안전(Safety), 보안(Security), 포장(Packaging)","src":"기출 2021-5, 2023-2, 2024-1, 2026-5"}]},{"머리":"물류의 효과와 중요성","줄":[{"t":"물류 생산성 향상과 비용절감으로 물가상승을 억제","src":"기출 2021-1"},{"t":"물류 합리화로 유통구조를 선진화하고 사회간접자본 투자에 기여","src":"기출 2021-1"},{"t":"고객 요구에 따라 생산된 제품을 고객에게 전달하고 수요를 창출. 생산자와 소비자 사이의 인격적 유대를 강화하고 고객서비스를 높임","src":"기출 2021-1"},{"t":"물류비용 절감을 통한 이익 창출은 제3의 이익원","src":"기출 2023-6, 2025-6"},{"t":"물류관리의 목표: 비용절감을 통한 제품의 판매촉진과 수익증대","src":"기출 2023-6"},{"t":"물류관리는 구매·생산·마케팅과 밀접. 원자재·부품 조달, 구매상품 보관, 완제품 유통도 대상","src":"기출 2023-6, 2025-6"},{"t":"물류관리 대상: 고객서비스관리·재고관리·주문정보관리·운송관리. 인사관리는 대상이 아님","src":"기출 2023-1"},{"t":"중요성 증대 배경: 공급사슬 전체 경쟁력 강화, 생산부문 원가절감의 한계, 온라인쇼핑 증가에 따른 배송 중요성, 글로벌화에 따른 물동량 증가","src":"기출 2025-5"},{"t":"물류 합리화 추진 시 내부 기능 간 또는 기업 간 상충관계(trade-off) 발생 가능","src":"기출 2025-31"},{"t":"물류 합리화 추진 단계: 환경 분석 → 목표 설정 → 전략 수립","src":"기출 2025-31"},{"t":"지능형 자동화 기계를 물류 업무에 도입하는 것은 생지능형(省知能形) 합리화","src":"기출 2025-31"}]},{"머리":"유통활동 구분: 상적유통과 물적유통","줄":[{"t":"물적유통 활동: 보관, 화물수송, 유통가공, 정보관리","src":"기출 2021-2, 2025-2"},{"t":"상적유통 활동: 거래(상거래)활동, 금융조성활동, 표준화 활동","src":"기출 2021-2, 2025-2"}]},{"머리":"물류 6대 기능","줄":[{"t":"운송(수송): 물자의 장소적 효용가치를 증대. 물자를 물류거점 간 및 고객에게 이동","src":"기출 2026-4, 2024-3"},{"t":"보관: 생산과 소비의 시기·수량 차이를 조정, 시간적 효용가치를 증대","src":"기출 2021-14, 2026-4, 2022-20"},{"t":"하역: 운송·보관·포장 사이에 발생하는 물자 취급 활동. 운송과 보관을 위해 화물을 싣거나 내리는 행위","src":"기출 2021-14, 2022-20, 2024-3"},{"t":"포장: 적절한 재료·용기로 물자를 보호하고 취급을 용이하게 하며 상품가치를 제고. 생산의 종착점이자 물류의 출발점이므로 표준화·모듈화가 중요","src":"기출 2021-14, 2022-20, 2024-3, 2026-4"},{"t":"유통가공: 유통과정에서 고객 요구에 부합하기 위해 행하는 단순 가공·재포장·조립·절단 등","src":"기출 2024-3, 2026-4, 2022-20"},{"t":"정보관리: 물류계획 수립과 통제에 필요한 자료를 수집·활용. 전자적 수단으로 물류활동을 효율화","src":"기출 2021-14, 2022-20, 2024-3"},{"t":"수송은 물류거점 간 대량·장거리 이동, 배송은 소량·단거리로 고객에게 인도하는 것으로 구분","src":"보충"}]},{"머리":"물류의 영역별 분류","줄":[{"t":"조달물류: 물자의 조달처로부터 운송되어 매입자의 보관창고에 입고·관리되어 생산공정에 투입되기 직전까지의 물류활동","src":"기업물류비 산정지침 제7조 제1항 제1호, 기출 2022-22"},{"t":"사내물류(생산물류): 자재가 생산공정에 투입된 때부터 제품이 완성되기까지의 물류활동","src":"기출 2022-22, 2024-7, 2026-2"},{"t":"판매물류: 완제품이 판매창고에 입고된 후 고객에게 인도될 때까지의 물류활동","src":"기업물류비 산정지침 제7조 제1항 제3호, 기출 2026-2"},{"t":"역물류: 반품물류·폐기물류·회수물류를 포함하며 순물류와 반대 방향으로 이동","src":"기출 2022-22, 2024-7, 2025-1"},{"t":"회수물류: 판매물류를 지원하는 파렛트·컨테이너 등 포장용기·물류용기의 회수 활동","src":"기출 2022-22, 2024-7, 2026-2, 2025-1"},{"t":"반품물류는 고객요구 다양화·클레임 증가·유통채널 경쟁·전자상거래 확대로 중요성이 커짐","src":"기출 2021-3"},{"t":"영역별 분류에 정보물류는 없다","src":"기출 2023-5"}]},{"머리":"물류산업과 물류시설","줄":[{"t":"물류사업: 화물운송업·물류시설운영업·물류서비스업·종합물류서비스업","src":"물류정책기본법 제2조 제1항 제2호"},{"t":"물류서비스업: 화물운송의 주선, 물류장비의 임대, 물류정보의 처리, 물류컨설팅 등","src":"물류정책기본법 제2조 제1항 제2호 다목"},{"t":"물류시설운영업: 물류터미널이나 창고 등 물류시설을 운영","src":"물류정책기본법 제2조 제1항 제2호 나목"},{"t":"(2021 기출 당시 보기 분류) 하역·포장·가공·조립·상표부착·프로그램 설치·품질검사 등 부가 서비스 사업은 화물취급업","src":"기출 2021-6"},{"t":"물류체계: 효율적인 물류활동을 위하여 시설·장비·정보·조직 및 인력 등이 유기적으로 기능하도록 연계된 집합체","src":"물류정책기본법 제2조 제1항 제3호"},{"t":"데포(Depot): 국내용 2차 창고 또는 수출화물의 집화·분류·운송을 위한 내륙 CFS처럼, 대량 통합운송된 화물을 일시 보관하는 창고","src":"기출 2023-14"},{"t":"물류시설 용어: 물류터미널, 집배송센터, 공동집배송단지, 물류센터, 데포","src":"기출 2023-14"}]}],"함정":[{"x":"공급사슬관리를 통해 개별 기업의 독자적 경영 최적화를 달성한다.","o":"공급사슬관리는 공급사슬 전체의 최적화를 추구한다.","src":"기출 2021-5, 2025-3"},{"x":"수송기능은 물류 거점과 소비 공간을 연결하는 소량 화물의 단거리 이동을 말한다.","o":"수송은 물류거점 간 대량·장거리 이동, 소량·단거리 인도는 배송(교재 구분, 추정).","src":"기출 2021-14, 보충(추정)"},{"x":"물류 합리화를 위해서 물류하부시스템의 개별적 비용절감이 전체시스템의 통합적 비용절감보다 중요하다.","o":"전체시스템의 통합적 비용절감(총비용 관점)이 개별 하부시스템 비용절감보다 중요하다.","src":"기출 2022-1"},{"x":"운송활동은 생산시기와 소비시기의 불일치를 해결하는 기능을 수행한다.","o":"생산시기와 소비시기의 불일치를 조정하는 것은 보관활동. 운송은 장소적 효용.","src":"기출 2022-20"},{"x":"한국 물류정책기본법상 물류는 운송, 보관, 하역 등이 포함되며 가공, 조립, 포장 등은 포함되지 않는다.","o":"물류에는 운송·보관·하역과 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등이 포함된다.","src":"물류정책기본법 제2조 제1항 제1호"},{"x":"사내물류 - 완제품의 판매로 출하되어 고객에게 인도될 때까지의 물류활동이다.","o":"그 설명은 판매물류. 사내물류는 생산공정 투입 후 제품 완성까지(또는 매입물자 보관창고~판매 장소까지).","src":"기출 2022-22, 2024-7, 기업물류비 산정지침 제7조 제1항 제2호"},{"x":"최근 전자상거래 활성화에 따라 물동량은 증가하는 반면 물류관리의 역할은 줄어들고 있다.","o":"전자상거래 활성화로 물동량이 늘면서 물류관리의 역할은 커지고 있다.","src":"기출 2023-6"},{"x":"생산단계에서 소비단계로의 전체적인 물적 흐름으로 조달부문을 제외한 모든 활동이다.","o":"물류(Logistics)는 조달부문을 포함한다.","src":"기출 2023-11"},{"x":"7R 원칙은 적절한 상품(Commodity), 품질(Quality), 수량(Quantity), 시간(Time), 장소(Place), 보안(Security), 가격(Price)이다.","o":"7R의 일곱째는 보안이 아니라 인상(Impression).","src":"기출 2024-1"},{"x":"보관활동은 물자를 수요가 낮은 국가에서 높은 국가로 이동시켜 물자의 효용가치를 증대시키기 위한 물류활동이다.","o":"그 설명은 운송(장소적 효용). 보관은 시간적 효용.","src":"기출 2024-3"},{"x":"사내물류는 완제품의 판매로 출하되어 고객에게 인도될 때까지의 물류활동이다.","o":"판매물류의 설명이다.","src":"기출 2024-7"},{"x":"물류는 통합적 물류관리의 개념에서 출발하여 물류영역 전반의 최적화를 거쳐 최종적으로 개별 기업의 물류생산성 제고의 차원으로 발전하였다.","o":"부문별 효율화(물적유통) → 기업 내 효율화(로지스틱스) → 공급사슬 전반(SCM)으로 확대되었다.","src":"기출 2025-3"},{"x":"소비자 니즈(needs)의 다양화로 소품종 대량생산이 증가하여 물류관리의 중요성이 증가하고 있다.","o":"다품종 소량생산이 증가하여 중요성이 커졌다.","src":"기출 2025-5"},{"x":"물류는 마케팅믹스의 4P 중 제품(product)과 가장 밀접한 관계가 있다.","o":"4P 중 유통(Place)과 가장 밀접.","src":"기출 2025-6"},{"x":"물적유통은 자재관리를 포함하는 물류개념이다.","o":"출제 오답(바른 서술 미확인). 자재관리를 포함하는 것은 로지스틱스 쪽으로 정리됨(추정).","src":"기출 2026-1"},{"x":"로지스틱스는 완성품을 소비자에게 유통하는 물류관리활동을 의미한다.","o":"완성품을 소비자에게 유통하는 활동은 물적유통(판매영역 중심)이다. 로지스틱스는 조달·생산·판매·회수를 포함.","src":"기출 2026-1, 2024-1"},{"x":"AMA(American Marketing Association)는 로지스틱스를 “생산지로부터 소비지까지 제품을 이동하고 취급하는 것”으로 정의한다.","o":"출제 오답(바른 수치 미확인). 그 정의는 물적유통(PD) 정의로 정리됨(추정).","src":"기출 2026-1, 보충(추정)"},{"x":"시대의 흐름에 따라 물류의 개념은 로지스틱스에서 물적유통관리로 발전되었다.","o":"물적유통 → 로지스틱스 → SCM 순서로 발전.","src":"기출 2026-1, 2025-3"},{"x":"리버스(Reverse)물류란 생산과정에서 발생한 불량품을 제조공정으로 재투입하는 물류활동이다.","o":"리버스물류는 회수·폐기·반품물류를 포함. 소비자로부터 회수되어 폐기될 때까지의 흐름.","src":"기출 2026-2, 기업물류비 산정지침 제7조 제1항 제4호"}]},"#2":{"묶음":[{"머리":"물류환경 변화 방향","줄":[{"t":"국가 차원의 글로벌 종합물류기업 육성정책 시행","src":"기출 2021-4, 2024-2"},{"t":"e-비즈니스 확산으로 Door-to-Door 일관배송, 당일배송 증가. 전자상거래·홈쇼핑·온라인쇼핑으로 택배시장 확대","src":"기출 2021-4, 2024-2, 2025-4"},{"t":"유통가공·맞춤형 물류기능 확대 등 고부가가치 물류서비스 발전","src":"기출 2021-4"},{"t":"수요예측 등 종합적 물류계획의 수립·관리가 중요해짐","src":"기출 2021-4, 2024-2"},{"t":"노동력 부족·공해·교통 문제·지가 상승 등 사회적 환경변화로 물류비 절감의 중요성이 증가","src":"기출 2022-24"},{"t":"소품종 대량생산 → 다품종 소량생산으로 변화. 소량·다빈도 배송 증가","src":"기출 2022-24, 2026-3, 2025-4"},{"t":"국제화·글로벌 전략으로 국제물류의 중요성이 증가하고 물류관리 범위가 확대","src":"기출 2022-24, 2026-3"},{"t":"기후변화·친환경 물류정책으로 녹색물류 중요성이 증가하고 탄소배출 감축 방향으로 변화. 물류활동 폐기물 최소화 요구","src":"기출 2022-24, 2023-7, 2026-3"},{"t":"경제규모 확대에 따른 화물량 증가로 SOC 수요는 급증하나 물류 기반시설이 부족해 기업 원가부담이 가중","src":"기출 2023-7"},{"t":"정보기술·자동화기술 확산으로 물류작업의 고속화·효율화, 적정 재고관리 추진","src":"기출 2023-7"},{"t":"소비자 니즈 다양화와 제품 수명주기 단축으로 과잉재고를 지양하는 경향 심화","src":"기출 2023-7"},{"t":"하역의 로봇화, 화물의 단위적재 도입 등으로 물류 신속화·자동화 추구","src":"기출 2025-4"},{"t":"물류서비스 향상·비용절감을 위해 아웃소싱과 3PL 활용","src":"기출 2024-2, 2025-4"},{"t":"기업 간 경쟁 심화는 물류비용을 증대시키는 요인으로 작용","src":"기출 2026-3"}]}],"함정":[{"x":"기업의 핵심역량 강화를 위해서 물류기능을 직접 수행하는 화주기업이 증가하는 추세이다.","o":"핵심역량 강화를 위해 물류를 외부에 위탁(아웃소싱·3PL)하는 화주기업이 증가하는 추세이다.","src":"기출 2021-4, 2024-2"},{"x":"전자상거래의 확산으로 인해 라스트마일(Last Mile) 물류비가 감소하고 있다.","o":"출제 오답(바른 수치 미확인). 라스트마일 물류의 중요성과 비용 부담은 커지고 있다(추정).","src":"기출 2022-24, 보충(추정)"},{"x":"소비자 니즈(Needs)의 다양화에 따라 상품의 수요패턴이 소품종, 대량화되고 있다.","o":"다품종, 소량화되고 있다.","src":"기출 2023-7"},{"x":"소비자 중심 물류로의 전환으로 인하여 소품종 대량생산의 중요성이 증가하고 있다.","o":"다품종 소량생산이 늘어난다.","src":"기출 2024-2"},{"x":"물류의 중요성이 증가하여 상물일치의 개념이 확대되고 있다.","o":"상류(거래)와 물류를 분리하는 상물분리가 확대되고 있다(추정).","src":"기출 2025-4, 2026-3, 보충(추정)"},{"x":"물류의 중요성이 높아짐에 따라 상물일치의 개념이 확산되고 있다.","o":"상물분리의 개념이 확산(추정).","src":"기출 2026-3, 보충(추정)"}]},"#3":{"묶음":[{"머리":"물류관리 원칙 (2024 기출)","줄":[{"t":"신뢰성의 원칙: 필요한 물량을 원하는 시기와 장소에 공급하여 사용할 수 있도록 보장","src":"기출 2024-4"},{"t":"균형성의 원칙: 생산·유통·소비에 필요한 물자의 수요와 공급 및 조달과 분배의 균형 유지","src":"기출 2024-4"},{"t":"단순성의 원칙: 불필요한 유통과정을 제거하여 물자지원체계를 단순화·간소화","src":"기출 2024-4"},{"t":"경제성의 원칙: 최소한의 자원으로 최대한의 물자공급 효과를 추구하여 물류관리 비용을 최소화","src":"기출 2024-4"},{"t":"저장시설 보호 및 도난·망실·화재·파손 등으로부터 화물을 보호하는 원칙은 경제성이 아닌 다른 원칙(원칙명 미확인)","src":"기출 2024-4"}]},{"머리":"물류시스템 설계·관리의 기본 개념","줄":[{"t":"물류시스템 설계·범위 결정의 기준은 총비용 개념","src":"기출 2021-10"},{"t":"물류활동의 중심은 운송·보관·하역·포장 등이며 비용과 서비스 면에서 상충(trade-off) 관계","src":"기출 2021-10, 2022-26"},{"t":"취급 제품이 다양할수록 재고가 증가하고 비용상승 요인","src":"기출 2021-10"},{"t":"도로·철도·항만·공항 등 교통시설과의 접근성 고려","src":"기출 2021-10"},{"t":"고객서비스 달성 목표를 높이면 물류비용이 증가할 수 있음","src":"기출 2022-26"},{"t":"효과적 물류관리는 기능별 개별 물류비 절감보다 총물류비 절감","src":"기출 2024-8, 2026-10"},{"t":"물류서비스 수준은 매출액과 총물류비를 비교해 이윤이 극대화되는 수준으로 결정","src":"기출 2026-10"},{"t":"리드타임의 변동성은 안전재고 수준과 품절비용에 영향","src":"기출 2026-10"},{"t":"고객서비스 수준을 높이는 요인: EDI 도입, 리드타임 단축, 재고수준 상향, 물류거점 수 증가","src":"기출 2025-8"}]},{"머리":"물류관리 전략과 계획","줄":[{"t":"물류관리전략의 목표: 비용절감, 서비스 개선 등","src":"기출 2022-26"},{"t":"물류전략은 기업전략과 독립적이 아니라 기업전략에 연계되어 수립","src":"기출 2022-26, 2026-10"},{"t":"물류관리계획은 전략계획 → 전술계획 → 운영계획으로 단계적 수립","src":"기출 2022-26, 2025-6"},{"t":"제품수명주기별 물류전략: 도입기, 성장기, 성숙기, 쇠퇴기","src":"기출 2022-26, 2023-3, 2026-10"},{"t":"도입기: 거점 수·재고수준 결정 정보가 적어 물류관리자의 판단에 따른 계획이 필요","src":"기출 2025-9"},{"t":"성장기: 규모의 경제 달성 물류활동 필요, 비용과 서비스 간 상충관계를 본격 고려","src":"기출 2025-9"},{"t":"전략적 의사결정 활동 예: 시설 입지계획. 제품포장·재고통제·창고관리·주문품 발송은 운영적 활동","src":"기출 2021-9"}]},{"머리":"물류시스템 설계 수준 (Robeson & Copacino, James & William)","줄":[{"t":"수준 구분: 전략적 → 구조적 → 기능적 → 실행적(이행) 수준","src":"기출 2022-7, 2024-9"},{"t":"구조적 수준: 유통경로 설계, 네트워크 전략","src":"기출 2024-9"},{"t":"기능적 수준: 창고설계 및 운영, 수송관리, 자재관리","src":"기출 2022-7, 2026-9"},{"t":"고객서비스는 기능적·구조적 수준이 아님(전략적 수준으로 정리됨, 추정)","src":"보충(추정)"},{"t":"설비 및 장치는 기능적·구조적 수준이 아님(실행적 수준으로 정리됨, 추정)","src":"보충(추정)"}]},{"머리":"물류 합리화","줄":[{"t":"제조원가 절감을 통한 이익 증대가 어려워져 물류 효율성 제고 필요성 증가","src":"기출 2025-31"},{"t":"물류 합리화 시 내부 기능 간 또는 기업 간 상충관계 발생 가능","src":"기출 2025-31"}]}],"함정":[{"x":"소비자 서비스는 모든 제품에 대해서 동일한 수준으로 제공되어야 한다.","o":"제품별로 서비스 수준을 차등화한다.","src":"기출 2021-10"},{"x":"물류관리의 중요성이 높아짐에 따라 물류전략은 기업전략과 독립적으로 수립되어야 한다.","o":"물류전략은 기업전략에 정합되게 수립한다.","src":"기출 2022-26"},{"x":"물류전략은 기업전략(Corporate strategy)의 상위개념으로 수립되어야 한다.","o":"물류전략은 기업전략의 하위전략으로 수립한다.","src":"기출 2026-10"},{"x":"제조업체가 핵심역량인 제조에 집중하기 위해서는 자가물류의 확대가 필요하다.","o":"핵심역량 집중을 위해서는 물류 아웃소싱(3PL) 확대가 필요하다.","src":"기출 2025-31"},{"x":"일반적으로 고객서비스 수준이 높아지면 물류비가 절감되고 매출액은 증가한다.","o":"서비스 수준이 높아지면 물류비는 증가한다(상충관계).","src":"기출 2021-8"},{"x":"고객만족을 위해 물류서비스 수준을 높이면 물류비는 절감된다.","o":"물류비는 증가한다.","src":"기출 2024-8"},{"x":"고객서비스 수준이 높아지면 물류비가 절감되고 매출액은 증가한다.","o":"서비스 수준이 높아지면 물류비는 증가한다.","src":"기출 2025-8"}]},"#4":{"묶음":[{"머리":"목표와 개념","줄":[{"t":"고객서비스의 목표: 고객만족을 통한 고객감동의 실현","src":"기출 2021-8"},{"t":"물류서비스의 목표: 서비스 향상과 물류비 절감을 통한 경영혁신","src":"기출 2021-8"},{"t":"경제적 관점의 최적 물류서비스 수준: 물류활동에 의한 이익을 최대화하는 수준","src":"기출 2021-8"},{"t":"고객서비스 수준은 시장점유율과 수익성에 영향","src":"기출 2021-8"},{"t":"고객 만족도는 기대(Expectation)수준과 성과(Performance)수준의 차이로 설명","src":"기출 2024-6"},{"t":"서비스 품질은 고객과 서비스 제공자 간 상호작용으로 결정","src":"기출 2024-6"},{"t":"제품 가용성(Availability) 정보제공은 물류서비스 신뢰성에 영향을 준다","src":"기출 2024-6"},{"t":"서비스 수준이 정해지지 않았다면 수익과 비용을 동시에 고려해 최적 서비스수준을 결정","src":"기출 2024-6"}]},{"머리":"SERVQUAL 5차원","줄":[{"t":"유형성(Tangibles)·신뢰성(Reliability)·반응성(대응성, Responsiveness)·확신성(Assurance)·공감성(Empathy)","src":"기출 2024-13, 2026-7"},{"t":"5차원이 아닌 것으로 출제: 무형성(Intangibility), 규칙성(Regularity)","src":"기출 2024-13, 2026-7"}]},{"머리":"LaLonde & Zinszer 물류서비스 요소","줄":[{"t":"거래 전 요소: 명시화된 회사 정책(고객서비스 명문화), 시스템의 유연성","src":"기출 2022-35, 2023-4"},{"t":"거래 시 요소: 재고품절 수준(재고수준), 주문 편리성, 시스템의 정확성","src":"기출 2022-35, 2023-4"},{"t":"거래 후 요소: 보증수리, 설치 및 조립, 제품추적, 고객클레임·불만 처리","src":"기출 2022-35, 2023-4, 2026-6"}]},{"머리":"주문주기와 시간 요소","줄":[{"t":"주문주기시간(Order Cycle Time): 고객이 제품을 주문해서 받을 때까지 걸리는 총 시간","src":"기출 2022-32"},{"t":"주문전달시간, 주문처리시간, 주문조립시간, 인도시간 등으로 구성","src":"기출 2022-32, 2025-7"},{"t":"주문조립시간(Order Assembly Time): 주문정보를 창고나 발송부서에 전달한 후부터 주문받은 제품의 발송을 준비하는 데 걸리는 시간","src":"기출 2025-7"}]},{"머리":"계산: 정시배송율","줄":[{"t":"공식: 정시배송율 = 지연 없이 완료된 건수 ÷ 전체 배송 완료 건수 × 100","src":"기출 2021-7"},{"t":"풀이 순서: 건별로 배송완료 일시가 배송예정 일시 이내인지 확인 → 이내인 건수 합계 → 전체 건수로 나눔","src":"기출 2021-7"},{"t":"예: 5건 중 3건이 예정시각 이내 완료 → 60%","src":"기출 2021-7"}]}],"함정":[{"x":"제품 가용성(Availability) 정보제공은 물류서비스 신뢰성에 영향을 주지 않는다.","o":"제품 가용성 정보제공은 신뢰성에 영향을 준다.","src":"기출 2024-6"}]},"#5":{"묶음":[{"머리":"유형 분류 관점 (2022 기출)","줄":[{"t":"형태 관점: 사내조직, 독립자회사","src":"기출 2022-5"},{"t":"관리 관점: 분산형, 집중형, 집중분산형","src":"기출 2022-5"},{"t":"기능 관점: 라인업무형, 스태프업무형, 라인스태프겸무형, 매트릭스형","src":"기출 2022-5"},{"t":"영역 관점: 개별형, 조달형, 마케팅형, 종합형, 로지스틱스형","src":"기출 2022-5"},{"t":"비공식·준공식·공식 조직 분류는 예산 관점이 아님(공식성 관점으로 정리됨, 추정)","src":"보충(추정)"}]},{"머리":"조직 형태별 특징","줄":[{"t":"분산형: 물류관리 업무를 각 공장·영업부서·운송부서·총무부서 등에서 개별적으로 운영","src":"기출 2024-11"},{"t":"자회사형: 물류관리 업무를 전문화해 독립된 회사로 분사","src":"기출 2024-11"},{"t":"그리드형: 다국적 기업에 많음. 모회사 물류본부의 스태프 부문이 여러 자회사의 해당 부문을 횡적으로 관리·지원","src":"기출 2021-12"},{"t":"사업부형: 기업 규모 확대에 따라 등장. 각 사업단위의 성과 극대화, 독립채산제, 물류 전문 인재 양성 용이","src":"기출 2025-10, 2026-11"},{"t":"사업부형 단점: 물류기능 중복으로 조직운영 비용이 큼, 전문인력 교류 경직, 전사적 통합성 결여로 경영효율 저하","src":"기출 2026-11, 2025-10"},{"t":"물류조직 유형 보기: 직능형, 사업부형, 라인스태프형, 그리드형, 매트릭스형, 기능특성형","src":"기출 2021-12, 2025-10, 2026-11"}]}],"함정":[{"x":"예산관점에서 비공식적, 준공식적, 공식적 조직으로 분류할 수 있다.","o":"출제 오답(바른 수치 미확인). 비공식·준공식·공식 분류는 공식성 관점(추정).","src":"기출 2022-5, 보충(추정)"}]},"#6":{"묶음":[{"머리":"지침의 성격","줄":[{"t":"기업물류비 산정지침은 물류정책기본법 제26조 및 영 제18조에 따라 물류기업·화주기업의 물류비 계산 절차와 방법의 기준을 제공. 목적은 물류회계 표준화와 물류비 산정의 정확성·관리 합리성 제고","src":"기업물류비 산정지침 제1조"},{"t":"물류비: 물류활동을 수행하기 위하여 발생하거나 소비한 경제가치","src":"기업물류비 산정지침 제2조 제2호"},{"t":"적용대상: 물류비 실적측정용. 제조업, 유통업(도·소매업 등), 물류업(수송업 등)","src":"기업물류비 산정지침 제3조"},{"t":"구성: 원가회계방식으로 별도 원가자료로부터 물류비를 계산하는 일반기준 + 재무회계방식으로 회계장부·재무제표로부터 물류비를 추산하는 간이기준","src":"기업물류비 산정지침 제4조"},{"t":"일반기준은 관리회계(원가회계) 방식, 간이기준은 재무제표 중심의 재무회계 방식. 간이기준은 정확한 물류비 파악이 어려움","src":"기업물류비 산정지침 제4조, 기출 2022-17"},{"t":"기업은 매출규모, 매출액 대비 물류비 비중, 물류비 변동 등을 고려해 일반기준과 간이기준을 선택하여 적용할 수 있다","src":"기업물류비 산정지침 제5조 제1항"},{"t":"물류비 계산범위는 국내에서 발생하는 물류비로 제한","src":"기업물류비 산정지침 제5조 제2항"}]},{"머리":"일반기준: 과목 분류 체계","줄":[{"t":"일반기준 분류: 영역별·기능별·지급형태별·세목별(실태 파악) + 관리항목별·조업도별(관리 목적)","src":"기업물류비 산정지침 제7조"},{"t":"영역별 물류비: 조달물류비·사내물류비·판매물류비·리버스(역)물류비","src":"기업물류비 산정지침 제7조 제1항, 기출 2022-17, 2026-20"}]},{"머리":"일반기준: 영역별","줄":[{"t":"조달물류비: 조달처에서 운송되어 매입자 보관창고 입고·관리, 생산공정 투입 직전까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제1호"},{"t":"사내물류비: 매입물자 보관창고에서 완제품 등의 판매를 위한 장소까지의 물류활동 비용","src":"기업물류비 산정지침 제7조 제1항 제2호"},{"t":"재료의 생산이나 제품 제조공정 내 발생 비용은 생산원가·제조원가에 산입되므로 물류비에서 제외","src":"기업물류비 산정지침 제7조 제1항 제2호"},{"t":"판매물류비: 완제품·상품을 판매창고에서 보관하는 활동부터 고객에게 인도될 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제3호"},{"t":"리버스물류비: 회수물류비·폐기물류비·반품물류비로 세분","src":"기업물류비 산정지침 제7조 제1항 제4호"},{"t":"회수물류비: 공용기·포장자재 등이 회수되어 재사용 가능할 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 가목"},{"t":"폐기물류비: 제품·상품, 포장용·수송용 용기나 자재 등을 회수하여 폐기할 때까지의 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 나목"},{"t":"반품물류비: 판매한 제품·상품 또는 위탁판매 제품·상품의 취소, 위탁의 취소 등 물류활동에 따른 물류비","src":"기업물류비 산정지침 제7조 제1항 제4호 다목"}]},{"머리":"일반기준: 기능별","줄":[{"t":"운송비: 물자를 물류거점 간 및 고객에게 이동시키는 활동 비용. 수송비(물류거점까지 이동)·배송비(고객에게 배달)로 세분 가능","src":"기업물류비 산정지침 제7조 제2항 제1호"},{"t":"보관비: 물자를 창고 등 물류시설에 보관하는 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제2호"},{"t":"하역비: 유통가공·운송·보관·포장 등에 수반하여 상차·하차, 피킹, 분류 등 물자를 상하·좌우로 이동시키는 비용","src":"기업물류비 산정지침 제7조 제2항 제3호"},{"t":"포장비: 물자 이동·보관을 쉽게 하기 위한 상자·골판지·파렛트 등 물류포장 비용. 최종소비자를 위한 판매포장은 제외","src":"기업물류비 산정지침 제7조 제2항 제4호"},{"t":"물류정보·관리비: 물류활동·기능 관련 정보처리와 관리 비용. 물류정보비와 물류관리비로 세분 가능","src":"기업물류비 산정지침 제7조 제2항 제5호"},{"t":"물류정보비: 구매·수송·생산·창고운영·재고관리·유통망 등 물류 프로세스를 전자적 수단으로 지원하는 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제5호 가목"},{"t":"물류관리비: 물류활동·기능의 합리화와 공동화를 위한 계획·조정·통제 등 관리 활동 비용","src":"기업물류비 산정지침 제7조 제2항 제5호 나목"}]},{"머리":"일반기준: 지급형태별·세목별","줄":[{"t":"자가물류비: 자사 설비·인력으로 물류활동을 수행해 소비된 비용. 재료비·노무비·경비·이자로 구분","src":"기업물류비 산정지침 제7조 제3항 제1호"},{"t":"위탁물류비: 물류활동의 일부·전부를 타사에 위탁해 소비된 비용. 물류자회사 지급분과 물류전문업체 지급분으로 구분","src":"기업물류비 산정지침 제7조 제3항 제2호"},{"t":"세목별 분류: 재료비·노무비·경비·이자","src":"기업물류비 산정지침 제7조 제4항 제1호, 기출 2025-16"},{"t":"시설부담이자: 물류시설에 투자된 자금의 이자부담분만큼의 기회손실","src":"기업물류비 산정지침 제7조 제4항 제2호"},{"t":"재고부담이자: 재고자산 가치에 대한 이자부담분만큼의 기회손실. 보관비에만 포함. 재고는 자가·영업창고 보관 원자재·부품·제품 일체","src":"기업물류비 산정지침 제7조 제4항 제2호"}]},{"머리":"일반기준: 관리 목적 분류","줄":[{"t":"관리항목별: 조직별·지역별·고객별·활동별 등 관리항목을 정의해 구분","src":"기업물류비 산정지침 제7조 제5항"},{"t":"조업도별: 물류고정비(조업도 증감과 무관하게 일정)·물류변동비(조업도 증감에 비례)","src":"기업물류비 산정지침 제7조 제6항"}]},{"머리":"인식·계산 방법","줄":[{"t":"인식 기준: 원칙적으로 발생기준. 시설부담이자·재고부담이자는 기회원가 개념 적용","src":"기업물류비 산정지침 제8조"},{"t":"물류비 계산은 실태파악 목적(영역별·기능별·지급형태별)과 관리 목적(조업도별·관리항목별)으로 구분","src":"기업물류비 산정지침 제9조"},{"t":"물류활동과 관련된 것만 계산하고 비정상적인 물류비는 제외","src":"기업물류비 산정지침 제9조 제1항 제1호"},{"t":"부수적·간접적 물류비는 합리적 배부기준(금액·인원·면적·시간·물량 등)으로 배부","src":"기업물류비 산정지침 제9조 제1항 제4호, 제5호"},{"t":"관리항목별 계산: 직접귀속 가능한 직접비는 직접 부과, 불가능한 간접비는 적절한 배부기준으로 배부","src":"기업물류비 산정지침 제9조 제2항 제2호"},{"t":"시설부담이자·재고부담이자는 자산명세서·재고명세서와 권위 있는 기관의 이자율로 계산","src":"기업물류비 산정지침 제9조 제2항 제3호"},{"t":"일반기준 적용 기업은 매 회계연도 당기·전기 실적을 비교하는 별지 제1호 서식 계산서 작성","src":"기업물류비 산정지침 제10조"}]},{"머리":"간이기준","줄":[{"t":"간이기준 목적: 물류비 실태를 추정할 목적. 재무회계방식으로 회계장부·재무제표로부터 기능별·지급형태별로 계산","src":"기업물류비 산정지침 제11조"},{"t":"간이기준 기능별: 운송비, 보관비, 하역비, 포장비, 물류정보·관리비","src":"기업물류비 산정지침 제12조 제1항"},{"t":"간이기준 지급형태별: 자가물류비(재료비·노무비·경비·이자), 위탁물류비","src":"기업물류비 산정지침 제12조 제2항"},{"t":"간이기준 계산: 제조원가명세서·손익계산서 계정과목별로 물류비 해당 금액을 추계","src":"기업물류비 산정지침 제13조 제1항"},{"t":"간이기준에서 시설부담이자·재고부담이자는 자산명세서·재고명세서 기초로 계산","src":"기업물류비 산정지침 제13조 제2항"},{"t":"간이기준 적용 기업은 별지 제2호 서식 계산서 작성","src":"기업물류비 산정지침 제14조"}]},{"머리":"계산: 간접물류비 배부 (품목별)","줄":[{"t":"풀이 순서: 비목별 간접물류비 총액 확인 → 비목별 배부기준(운송비=운송물량×운송거리, 보관비=보관공간×보관일수, 하역비=상차수량+하차수량)으로 품목별 값 산출 → 품목별 비율 → 비목 총액×비율 → 품목별로 합산","src":"기출 2023-20"},{"t":"예: 운송비 10,000 중 15×250:10×125=3,750:1,250 → 7,500:2,500. 보관비 2,000 중 500×3:300×15=1,500:4,500 → 500:1,500. 하역비 1,000 중 9,000:1,000 → 900:100. P1=8,900, P2=4,100","src":"기출 2023-20"}]},{"머리":"계산: 판매물류비 집계","줄":[{"t":"풀이 순서: 각 지출을 영역으로 분류 → 판매물류비 항목(완제품 출고검사, 완제품 포장, 상차·배송)만 합산. 생산공정 투입 제조비(제조원가)는 물류비에서 제외","src":"기출 2024-17, 기업물류비 산정지침 제7조 제1항 제2호"},{"t":"예: 출고검사 20 + 포장 50 + 상차·배송 30 = 100만원","src":"기출 2024-17"}]},{"머리":"계산: 평균 보관체적 비례 배부","줄":[{"t":"풀이 순서: 제품별 연평균 보관량 = (기초재고+기말재고)÷2 → × 단위당 체적 = 연평균 보관체적 → 체적 비율 → 임대료 × 비율","src":"기출 2026-19"},{"t":"예: A (230+270)÷2×1.0=250, B (120+80)÷2×1.5=150 → 5,000만원 중 A 3,125, B 1,875","src":"기출 2026-19"}]}],"함정":[{"x":"재료비는 기능별 물류비 비목이다.","o":"재료비는 세목별(자가물류비의 세목) 비목. 기능별은 운송비·보관비·하역비·포장비·물류정보관리비.","src":"기출 2021-15, 기업물류비 산정지침 제7조"},{"x":"위탁비는 일반기준 기능별 물류비에 해당한다.","o":"위탁물류비는 기능별이 아니라 지급형태별 분류.","src":"기출 2023-15, 기업물류비 산정지침 제7조 제3항"},{"x":"물류기업의 물류비 산정 정확성을 높이기 위해 개발되었으므로 화주기업은 적용 대상이 될 수 없다.","o":"지침은 제조업·유통업·물류업을 대상으로 하므로 화주기업도 적용 대상이다.","src":"기출 2022-17, 기업물류비 산정지침 제3조"},{"x":"사내물류비는 제조공정 내에서 발생한 비용과 공정 간 물류비용을 포함한다.","o":"제조공정 내 발생 비용은 생산원가·제조원가에 산입되므로 물류비에서 제외한다.","src":"기출 2026-20, 기업물류비 산정지침 제7조 제1항 제2호"}]},"#7":{"묶음":[{"머리":"활동기준원가계산 (ABC)","줄":[{"t":"정의: 기업이 수행하는 활동을 기준으로 자원·활동·원가대상의 원가와 성과를 측정하는 원가계산방법","src":"기출 2022-18"},{"t":"업무를 활동단위로 세분하여 원가를 산출","src":"기출 2021-16"},{"t":"전통적 원가계산보다 제품·서비스의 실제 비용을 현실적으로 계산","src":"기출 2022-18"},{"t":"활동별로 원가를 분석하므로 낭비요인이 있는 업무 영역을 파악","src":"기출 2021-16, 2022-18"},{"t":"산정원가로 원가유발요인분석과 성과측정 가능","src":"기출 2021-16"},{"t":"물류서비스별·활동별·고객별·유통경로별·프로세스별 수익성 분석 가능","src":"기출 2021-16"},{"t":"소품종 대량생산보다 다품종 소량생산에서 유용성이 더 높음","src":"기출 2022-18"},{"t":"재료비·노무비·경비로 구분하는 계산은 전통적(비목별) 원가계산 방식","src":"기출 2021-16"},{"t":"전통적 원가계산의 문제: 임의적인 간접원가 배부기준(ABC가 극복하려는 대상)","src":"기출 2022-18"}]},{"머리":"균형성과표 (BSC, Kaplan & Norton)","줄":[{"t":"4가지 관점: 재무적 관점, 고객 관점, 내부 경영프로세스(내부 비즈니스 프로세스) 관점, 학습과 성장 관점","src":"기출 2021-18, 2022-19"},{"t":"전략적 관점은 4관점에 속하지 않는다","src":"기출 2021-18"},{"t":"재무성과뿐 아니라 전략실행에 필요한 비재무적 정보 제공. 전략과 관련된 측정지표의 집합","src":"기출 2022-19"},{"t":"무형자산을 차별화 전략이나 주주가치로 변환시키는 기법. 경영자의 단기적·재무적 근시안을 균형있게 함","src":"기출 2022-19"},{"t":"전 조직원이 전략을 공유하고 전략방향에 따라 행동하도록 유도하는 성과 측정 방법","src":"기출 2021-18"}]},{"머리":"손익분기점(BEP)","줄":[{"t":"공식: 손익분기점 판매량 = 고정비 ÷ (단위당 판매가격 − 단위당 변동비)","src":"기출 2021-17, 2022-16, 2024-20, 2025-14"},{"t":"손익분기점 매출액 = 고정비 ÷ 공헌이익률 (공헌이익률 = 1 − 변동비율)","src":"기출 2023-18"},{"t":"목표이익 달성 판매량 = (고정비 + 목표이익) ÷ 단위당 공헌이익","src":"기출 2021-17"},{"t":"풀이 순서: 단위당 변동비 계산(가격×변동비율) → 단위당 공헌이익 → 고정비를 나눔 → (목표이익 있으면 분자에 더함)","src":"기출 2021-17"},{"t":"예: 고정비 1억, 가격 10만, 변동비 60% → 공헌이익 4만 → BEP 2,500개, 목표이익 1억 포함 5,000개","src":"기출 2021-17"},{"t":"예: 고정비 10억, 가격 10만, 변동비 50% → 공헌이익 5만 → 20,000개, 매출 20억","src":"기출 2022-16"},{"t":"예: 가격 10만, 변동비 7.5만, 고정비 1억 → 공헌이익률 25% → BEP 매출 4억(40,000만원)","src":"기출 2023-18"},{"t":"예: 고정비 2천만원, 가격 1만, 변동비 80% → 공헌이익 2천 → 10,000개","src":"기출 2024-20"},{"t":"예: 고정비 2억, 가격 10만, 변동비 75% → 공헌이익 2.5만 → 8,000개","src":"기출 2025-14"}]},{"머리":"물류비 절감 효과와 이익률","줄":[{"t":"물류비 절감액은 그대로 이익 증가분. 동일 이익을 매출로 얻으려면 필요 매출 = 절감액 ÷ 이익률(경상이익률)","src":"기출 2024-5"},{"t":"예: 물류비 200억 5% 절감 = 10억, 경상이익률 60÷3000 = 2% → 필요 매출 500억","src":"기출 2024-5"},{"t":"예: 매출 400억, 물류비 20%=80억, 영업이익 20억 → 물류비 15%=60억이면 이익 40억 → 이익률 10%","src":"기출 2025-17"}]},{"머리":"ROI·재무 지표","줄":[{"t":"ROI(총자본이익률) = 매출액순이익률 × 총자본회전율","src":"기출 2024-18"},{"t":"현금전환주기(Cash-to-Cash) = 재고기간 + 매출채권 회수기간 − 매입채무 지급기간","src":"기출 2024-19"},{"t":"예: 재고 3개월 + 매출채권 2개월 − 매입채무 3개월 = 2개월","src":"기출 2024-19"},{"t":"Cash-to-Cash Cycle Time: 원자재 구매비용을 지불한 날부터 제품 판매대금을 수금한 날까지 소요 시간","src":"기출 2023-24"}]},{"머리":"공급사슬 성과지표","줄":[{"t":"주문주기시간, 현금화 사이클타임(Cash-to-Cash), 공급사슬 배송성과(Delivery Performance to Request), 주문충족 리드타임, 공급사슬 생산유연성(Upside Production Flexibility)","src":"기출 2023-24"}]},{"머리":"감가상각","줄":[{"t":"정액법 연 감가상각액 = (취득원가 − 잔존가치) ÷ 내용연수","src":"기출 2026-16"},{"t":"예: (1억 − 2,000만) ÷ 10년 = 800만원","src":"기출 2026-16"}]},{"머리":"조업도와 고정·변동 물류비","줄":[{"t":"총물류비 = 고정물류비 + 변동물류비율 × 조업도","src":"기출 2026-18"},{"t":"풀이 순서: 전년 총물류비 계산 → 목표 조업도(전년×1.25) → (전년 총물류비 − 신규 고정비) ÷ 목표 조업도 = 필요한 변동비율","src":"기출 2026-18"},{"t":"예: 50 + 0.07×1,000 = 120억. 조업도 1,250. (120 − 60) ÷ 1,250 = 0.048","src":"기출 2026-18"}]},{"머리":"물류원가계산과 채산성분석","줄":[{"t":"물류원가계산: 예산기간 동안의 물류업무 활동실적을 평가하고 동일한 방식으로 예산기간별로 반복 수행","src":"기출 2026-21"},{"t":"물류채산성분석: 개선안의 채택 여부 등 의사결정에 활용. 분석 목적과 상황에 따라 적용 기법이 달라짐","src":"기출 2026-21"}]}],"함정":[{"x":"재료비, 노무비 및 경비로 구분하여 계산한다. (ABC의 설명으로)","o":"재료비·노무비·경비 구분은 전통적 원가계산. ABC는 활동 단위로 세분.","src":"기출 2021-16"},{"x":"임의적인 직접원가 배부기준에 의해 발생하는 전통적 원가계산방법의 문제점을 극복하기 위해 활용된다.","o":"임의적인 간접원가 배부기준의 문제를 극복하기 위해 활용(추정).","src":"기출 2022-18, 보충(추정)"},{"x":"기업의 성과를 비재무적 관점, 고객 관점, 내부 비즈니스 프로세스 관점, 학습 및 성장 관점에서 측정한다.","o":"재무적 관점, 고객 관점, 내부 프로세스 관점, 학습 및 성장 관점.","src":"기출 2022-19"},{"x":"ROI: 매출액순이익률과 손익분기점의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 재고회전율과 총자본회전율의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 재고회전율과 손익분기점의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"ROI: 손익분기점과 총자본회전율의 곱으로 표현할 수 있다.","o":"매출액순이익률과 총자본회전율의 곱.","src":"기출 2024-18"},{"x":"물류원가계산과 물류채산성분석은 시간에 따른 화폐 가치의 할인을 반영한다.","o":"출제 오답(바른 수치 미확인). 원가계산은 할인을 반영하지 않고, 채산성분석은 기법에 따라 달라짐(추정).","src":"기출 2026-21, 보충(추정)"}]},"#8":{"묶음":[{"머리":"물류정보의 특징","줄":[{"t":"관리대상 정보의 종류가 많고 내용이 다양","src":"기출 2021-23"},{"t":"성수기와 비수기의 정보량 차이가 큼","src":"기출 2021-23, 2023-36, 2026-25"},{"t":"정보의 발생원·처리장소·전달대상이 분산되어 있음","src":"기출 2021-23"},{"t":"상품과 정보의 흐름에 동시성이 요구됨","src":"기출 2021-23"},{"t":"구매·생산·영업활동과의 관련성이 큼","src":"기출 2021-23"}]},{"머리":"물류정보시스템(LIS)","줄":[{"t":"영어 약어 LIS. 물류정보의 수집·저장·가공·유통을 가능하게 하는 하드웨어·소프트웨어·업무프로세스·사용자 등의 집합체","src":"기출 2024-28, 2026-25"},{"t":"목적: 물류서비스 향상과 물류비 절감","src":"기출 2024-28, 2026-25, 2021-26"},{"t":"개별 물류활동의 통합을 통한 전체 최적화를 위해 구축","src":"기출 2024-28, 2026-25"},{"t":"정보량이 많을수록 수작업 대비 효율성·정확성 증대","src":"기출 2024-28"},{"t":"물류정보 시스템화는 상류정보(상거래 정보) 시스템화가 선행되어야 가능","src":"기출 2021-26"},{"t":"수주처리시스템: 최소의 주문입력 비용으로 고객서비스를 달성하는 것이 목적","src":"기출 2021-26"},{"t":"생산에서 소비까지 물류기능을 유기적으로 결합해 관리 효율성을 향상. 운송·보관·하역·포장 등 정보 포함","src":"기출 2023-36"}]},{"머리":"EDI","줄":[{"t":"EDI: 표준화된 상거래 서식으로 작성된 기업 간 전자문서교환 시스템. 거래업체 간 합의된 전자문서표준으로 컴퓨터 간 구조화된 데이터 전송","src":"기출 2021-26, 2023-40"},{"t":"효과: 정확한 실시간 업무 처리, 종이문서 수작업·처리 오류 감소, 국제 경쟁력 강화","src":"기출 2023-40"},{"t":"물류 EDI 도입 시 주문처리·물품추적·반품 영역에서 고객 만족도 향상","src":"기출 2025-8"},{"t":"국내에도 EDI 시스템 개발 사례가 있음(KL-NET, KT-NET 등)","src":"기출 2023-40, 보충"}]},{"머리":"VAN","줄":[{"t":"VAN(부가가치통신망): 부가가치를 부여한 음성 또는 데이터를 정보로 제공하는 광범위하고 복합적인 서비스의 집합","src":"기출 2021-25"},{"t":"VAN은 이용이 늘어나는 서비스. 한정된 지역의 장치를 연결하는 것은 LAN의 설명","src":"기출 2021-25, 보충"}]},{"머리":"POS","줄":[{"t":"POS(판매시점관리): 상품 판매 시점에 발생하는 정보를 저장하고, 실시간 매출 등록·자동정산·집계. 발주·구매·배송·재고관리와 연계","src":"기출 2023-37, 2025-25"},{"t":"소비동향이 반영된 판매정보를 실시간으로 파악해 판매·재고·고객관리 효율 향상","src":"기출 2021-26"}]},{"머리":"약어 연결","줄":[{"t":"TRS: 주파수공용통신","src":"기출 2022-13"},{"t":"ITS: 지능형교통정보시스템","src":"기출 2022-13"},{"t":"CVO: 첨단화물운송시스템","src":"기출 2022-13"},{"t":"KROIS: 철도화물정보망(철도운영정보시스템)","src":"기출 2022-13, 2024-27"},{"t":"POS: 판매시점관리","src":"기출 2022-13"},{"t":"CVO의 정식 영문은 Commercial Vehicle Operations","src":"보충"},{"t":"KL-NET: 물류거점 간 정보 및 물류 EDI 서비스. KT-NET: 무역정보망(무역자동화)","src":"보충"},{"t":"PORT-MIS: 해양수산부의 항만운영정보시스템","src":"보충"},{"t":"DPS(디지털 피킹 시스템): 랙·보관장소에 전자 표시기를 설치해 출고 품목의 보관구역·출고수량을 표시, 완료 시 신호가 꺼져 작업 완료 확인","src":"기출 2024-26, 2025-39"},{"t":"DAS(디지털 어소팅 시스템): 분배·분류 작업 지원(DPS와 구분)","src":"보충"}]},{"머리":"정보기술 용어","줄":[{"t":"ASP: 정보시스템을 자체 개발하는 것에 비해 구축기간이 짧음","src":"기출 2022-15, 보충"},{"t":"CALS: Computer Aided Acquisition & Logistics Support에서 Commerce At Light Speed로 발전","src":"기출 2022-15"},{"t":"CIM: 정보시스템으로 제조·개발·판매·물류 등 일련의 과정을 통합 관리하는 생산관리시스템","src":"기출 2022-15"},{"t":"IoT는 사물 간 통신 기술. 인간의 학습·추론·자연언어 이해능력을 컴퓨터로 구현한 기술은 인공지능(AI)","src":"기출 2022-15, 2024-40"},{"t":"QR코드는 컬러 격자무늬 패턴의 2차원 바코드(3차원 아님)","src":"기출 2022-15, 2025-23, 보충"},{"t":"GPS: 인공위성과의 무선교신으로 차량·선박 등의 위치를 파악","src":"기출 2025-25"}]},{"머리":"ERP","줄":[{"t":"ERP: 생산·판매·구매·인사·재무·물류 등 기업업무 전반을 통합 관리하는 정보시스템","src":"기출 2025-24, 2026-28"},{"t":"기업의 인적·물적 자원을 효율적으로 관리. 공급사슬 계획·실행 시스템에 필요한 정보 제공","src":"기출 2025-24, 2026-28"},{"t":"성공적 도입을 위해 업무 표준화와 프로세스 정비가 중요. 자재 조달·생산소요시간 단축 효과","src":"기출 2025-24, 2026-28"},{"t":"자재소요계획 MRP에서 MRP-II를 거쳐 ERP로 발전","src":"기출 2024-22, 2025-24"},{"t":"기업 내부 단위기능 중심의 생산성 향상이 아니라 전사 통합","src":"기출 2026-28"}]}],"함정":[{"x":"정보의 발생원, 처리장소, 전달대상 등이 한 곳에 집중되어 있다.","o":"물류정보의 발생원·처리장소·전달대상은 분산되어 있다.","src":"기출 2021-23"},{"x":"한정된 지역의 분산된 장치들을 연결하여 정보를 공유하거나 교환하는 것이다. (VAN)","o":"그 설명은 LAN. VAN은 부가가치통신망.","src":"기출 2021-25"},{"x":"컴퓨터 성능의 발달로 정보수집 능력이 우수한 대기업에 정보가 집중되므로 중소기업의 활용 가능성은 낮아지고 있다.","o":"중소기업의 활용 가능성은 높아진다(추정).","src":"기출 2021-25, 보충(추정)"},{"x":"1990년대 미국의 AT&T가 전화회선을 임대하여 특정인에게 통신 서비스를 제공한 것이 효시이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2021-25"},{"x":"VAN 서비스는 컴퓨터 성능 향상으로 인해 이용이 감소되고 있다.","o":"출제 오답(바른 수치 미확인). 이용이 감소한다는 서술이 틀림.","src":"기출 2021-25"},{"x":"물류정보시스템의 목적은 물류비가 증가하더라도 고객서비스를 향상시키는 것이다.","o":"물류서비스 향상과 물류비 절감이 목적이다.","src":"기출 2021-26"},{"x":"정보의 종류가 다양하고 규모가 크지만, 성수기와 평상시의 정보량 차이는 작다.","o":"성수기와 비수기의 정보량 차이가 크다.","src":"기출 2023-36"},{"x":"국제적으로는 다양한 EDI 시스템이 존재하지만, 국내 EDI 시스템 개발 사례는 존재하지 않는다.","o":"국내에도 EDI 시스템 개발 사례가 있다.","src":"기출 2023-40"},{"x":"개별 물류활동들의 통합을 통한 전체 최적화보다는 특정한 물류활동의 최적화를 위하여 구축한다.","o":"개별 활동 통합을 통한 전체 최적화를 위해 구축한다.","src":"기출 2024-28, 2026-25"},{"x":"개별 물류활동의 통합을 통한 전체 최적화보다 특정 물류활동의 최적화를 위하여 구축한다.","o":"개별 활동 통합으로 전체 최적화를 이루기 위해 구축한다.","src":"기출 2026-25"},{"x":"1970년대 생산현장 관리를 위해 개발된 MES(Manufacturing Execution System)에서 유래하였다.","o":"출제 오답(바른 수치 미확인). ERP는 MRP → MRP-II → ERP로 발전(보충).","src":"기출 2025-24"},{"x":"기업 내부의 단위기능 중심의 생산성 향상을 추구한다. (ERP)","o":"기업 전반(전사)의 통합 관리를 추구한다.","src":"기출 2026-28"},{"x":"ASP는 정보시스템을 자체 개발하는 것에 비해 구축기간이 오래 걸린다.","o":"ASP는 구축기간이 짧다.","src":"기출 2022-15"},{"x":"CALS 개념은 Commerce At Light Speed로부터 Computer Aided Acquisition & Logistics Support로 발전되었다.","o":"Computer Aided Acquisition & Logistics Support에서 Commerce At Light Speed로 발전.","src":"기출 2022-15"},{"x":"IoT(Internet of Things)는 인간의 학습능력과 지각능력, 추론능력, 자연언어의 이해능력 등을 컴퓨터 프로그램으로 실현한 기술을 의미한다.","o":"그 설명은 인공지능(AI).","src":"기출 2022-15"},{"x":"QR코드는 컬러 격자무늬 패턴으로 정보를 나타내는 3차원 바코드이다.","o":"QR코드는 2차원 바코드이다.","src":"기출 2022-15"},{"x":"KT-NET은 물류거점 간의 원활한 정보 및 물류 EDI 서비스를 제공한다.","o":"출제 오답(바른 수치 미확인). KT-NET은 무역정보망(보충).","src":"기출 2024-27, 보충"},{"x":"PORT-MIS는 항만 및 공항에 관한 정보를 제공하며 국토교통부에서 관리하는 정보망이다.","o":"출제 오답(바른 수치 미확인). 해양수산부 관리 항만정보시스템(보충).","src":"기출 2024-27, 보충"},{"x":"CVO는 Common Vehicle Operations의 약어이다.","o":"CVO는 Commercial Vehicle Operations(보충).","src":"기출 2024-27, 보충"},{"x":"KL-NET은 우리나라 최초의 무역정보망으로서 무역자동화 서비스를 제공한다.","o":"출제 오답(바른 수치 미확인). 무역자동화는 KT-NET(보충).","src":"기출 2024-27, 보충"}]},"#9":{"묶음":[{"머리":"GS1 표준코드와 EAN-13","줄":[{"t":"GS1 표준코드는 미국이 제정한 UPC와 유럽이 제정한 EAN 등을 표준화한 것","src":"기출 2021-24, 2026-27"},{"t":"EAN-13 구성: 국가식별코드 + 제조업체코드 + 상품품목코드 + 체크디지트(1자리)","src":"기출 2022-12, 2023-39"},{"t":"국가식별코드 2~3자리. 3자리 구성이며 1982년 이전 EAN International 가입국은 2자리","src":"기출 2022-12, 2023-39"},{"t":"제조업체코드: EAN-13(A) 4자리, EAN-13(B) 6자리","src":"기출 2022-12, 2023-39"},{"t":"상품품목코드: EAN-13(A) 5자리, EAN-13(B) 3자리","src":"기출 2022-12, 2023-39"},{"t":"체크디지트 1자리: 스캐너 판독 오류 방지","src":"기출 2022-12, 2023-39"},{"t":"EAN-13(B)는 취급 품목 수가 많은 기업에 활용","src":"기출 2022-12"},{"t":"EAN-13은 물류식별코드를 갖지 않음. 물류용기용은 GS1-14(ITF-14)처럼 물류식별코드를 가진 별도 코드","src":"기출 2023-39, 2026-27"},{"t":"GS1-14: 기업 간 거래 시 주로 골판지 박스에 사용. 물류식별코드·국가식별코드·제조업체코드·상품품목코드·체크디지트로 구성","src":"기출 2026-27"},{"t":"GS1-13의 처음 세 자리는 국가식별코드","src":"기출 2026-27"}]},{"머리":"1차원·2차원 바코드","줄":[{"t":"1차원 바코드: EAN-8, EAN-13, ITF-14, GS1-128","src":"기출 2024-24"},{"t":"2차원 바코드: PDF-417 등. 1차원보다 대량 데이터, 훼손·오염 시 오류 정정 용이, 텍스트·그래픽·사진 저장","src":"기출 2024-24, 2025-23"},{"t":"2차원 바코드 분류: 다층형(스택형)과 매트릭스형","src":"기출 2025-23, 2026-27"},{"t":"다층형: 1차원 바코드처럼 몇 개 문자가 수평으로 열을 구성하여 쌓음. Code 49, PDF-417","src":"기출 2026-27"},{"t":"매트릭스형: 정방형의 동일 폭 흑백요소를 모자이크식으로 배열. QR Code, Maxi Code","src":"기출 2026-27"},{"t":"QR코드 개발국: 일본(덴소웨이브). 미국 UPS가 개발한 것은 MaxiCode","src":"보충"}]},{"머리":"RFID","줄":[{"t":"RFID: 무선주파수 식별(Radio Frequency Identification). 바코드·스캐닝이 아닌 무선주파수 기반","src":"기출 2024-25, 2026-26"},{"t":"태그에 접촉하지 않아도 인식 가능","src":"기출 2022-11, 2024-25, 2026-26"},{"t":"바코드와 달리 읽고 쓰기(Read/Write) 가능. 태그 데이터 변경·추가 가능","src":"기출 2022-11, 2024-25"},{"t":"일시에 복수 태그 판독 가능","src":"기출 2022-11, 2025-25"},{"t":"바코드보다 가격이 비쌈. 개인정보 노출·사생활 침해 위험","src":"기출 2022-11"},{"t":"원거리·고속 이동 시에도 인식 가능. 반영구적 사용. 데이터 신뢰도 높음","src":"기출 2021-22"},{"t":"주파수 대역에 따라 태그 인식 거리와 인식 속도가 다름. 국가별 사용 주파수가 동일하지 않음","src":"기출 2024-25, 2021-22, 2026-26"},{"t":"능동형 태그: 내장 배터리 전원, 지속적 식별정보 송신, 수동형보다 비싸고 원거리 통신 가능, 반영구 사용은 불가(배터리 수명)","src":"기출 2023-38"},{"t":"수동형 태그는 지속적 식별정보 송신이 불가. 능동형은 송수신 모두 가능하고 구조가 복잡","src":"기출 2026-26, 보충"}]},{"머리":"신기술","줄":[{"t":"블록체인: 분산원장을 통해 거래기록을 참여자가 분산 보관, 투명성·신뢰성 확보. 해킹 방지를 위해 개발","src":"기출 2022-34, 2026-40"},{"t":"블록체인 유형: 퍼블릭, 프라이빗, 컨소시엄","src":"기출 2022-34"},{"t":"블록체인으로 화물 추적·관리 상황을 점검하고 운송 중 문제에 실시간 대처. 공급사슬 가시성·투명성 향상","src":"기출 2022-34, 2024-40, 2025-25"},{"t":"스마트물류의 특징: 초연결성, 초지능화, 공유경제","src":"기출 2024-40"},{"t":"IoT: 사물 간 통신으로 실시간 데이터 수집","src":"기출 2026-40"},{"t":"빅데이터: 공급사슬 데이터를 수집·저장·처리·분석·시각화","src":"기출 2024-40, 2026-40"},{"t":"AI: 자연어 처리, 시각적·인지적 인식 등으로 의사결정 지원","src":"기출 2024-40, 2026-40"},{"t":"클라우드 서비스: IaaS, PaaS, SaaS로 구분","src":"기출 2024-40"},{"t":"3D 프린팅: 쾌속조형(Rapid Prototyping)에서 유래. 다품종 소량생산 유리, 재고수준 감소, 시제품 제작시간 단축","src":"기출 2025-27"},{"t":"3D 프린팅은 고가의 금형제작 비용이 발생하지 않음","src":"기출 2025-27"}]}],"함정":[{"x":"태그 데이터의 변경 및 추가는 자유롭지만 일시에 복수의 태그 판독은 불가능하다.","o":"일시에 복수의 태그를 판독할 수 있다.","src":"기출 2022-11, 2025-25"},{"x":"상품품목 코드는 3자리로 구성된다. (EAN-13(A))","o":"상품품목코드는 EAN-13(A) 5자리, (B) 3자리.","src":"기출 2022-12"},{"x":"반영구적으로 사용 가능하다. (능동형 RFID 태그)","o":"능동형은 배터리 수명 때문에 반영구적이지 않다.","src":"기출 2023-38"},{"x":"EAN-13(A)와 EAN-13(B) 모두 물류용기에 부착하기 위한 물류식별코드를 가지고 있다.","o":"EAN-13에는 물류식별코드가 없다.","src":"기출 2023-39"},{"x":"바코드와 스캐닝 기술 기반으로 구축된다. (RFID)","o":"RFID는 무선주파수 기술 기반.","src":"기출 2024-25, 2026-26"},{"x":"2차원 바코드의 하나인 QR 코드는 미국의 UPS사가 개발하였다.","o":"QR코드는 일본 덴소웨이브 개발(보충).","src":"기출 2025-23, 보충"},{"x":"주파수 대역과 무관하게 태그 인식거리 및 인식속도는 동일한 성능을 발휘한다.","o":"주파수 대역에 따라 인식거리·속도가 다르다.","src":"기출 2026-26"},{"x":"수동형 태그는 지속적인 식별정보 송신이 가능하다.","o":"지속 송신은 능동형.","src":"기출 2026-26"},{"x":"능동형 태그는 전파의 수신만 가능하고 구조가 간단하다.","o":"능동형은 송수신 가능, 구조가 복잡(보충).","src":"기출 2026-26, 보충"},{"x":"GS1 표준코드는 미국에서 제정한 EAN과 유럽에서 제정한 UPC 등을 표준화한 것이다.","o":"미국 UPC, 유럽 EAN.","src":"기출 2026-27"},{"x":"1차원 바코드 GS1-13의 처음 세 자리는 물류식별코드를 의미한다.","o":"처음 세 자리는 국가식별코드.","src":"기출 2026-27"},{"x":"2차원 다층형 바코드는 정방형의 동일한 폭의 흑백요소를 모자이크식으로 배열하여 구성하며 QR Code, Maxi Code 등이 있다.","o":"그 설명은 매트릭스형. 다층형은 Code 49, PDF-417.","src":"기출 2026-27"},{"x":"2차원 매트릭스형 바코드는 1차원 바코드와 같이 몇 개의 문자가 모여 수평으로 열을 구성하며, Code 49, PDF-417 등이 있다.","o":"그 설명은 다층형. 매트릭스형은 QR Code, Maxi Code.","src":"기출 2026-27"},{"x":"사물인터넷(IoT)은 논리적인 문제해결뿐만 아니라 자연어처리, 시각적 및 인지적 인식 등의 물류정보처리를 위한 의사결정 기술이다.","o":"그 설명은 인공지능(AI).","src":"기출 2024-40"},{"x":"VAN 서비스는 IaaS, PaaS, SaaS 등으로 구분하며 사이버 보안을 강화한 기술이다.","o":"IaaS·PaaS·SaaS는 클라우드 서비스의 구분.","src":"기출 2026-40"},{"x":"고가의 금형제작 비용이 발생한다. (3D 프린팅)","o":"3D 프린팅은 금형이 필요 없다.","src":"기출 2025-27"}]},"#10":{"묶음":[{"머리":"SCM의 개념","줄":[{"t":"SCM: 원자재 조달, 생산, 고객에게 제품·서비스 제공까지 프로세스 지향적이고 통합적인 접근 방법","src":"기출 2021-27, 2026-31"},{"t":"가치사슬 관점에서 원자재부터 소비까지의 구성원을 하나의 집단으로 간주하여 물류와 정보 흐름을 체계적으로 관리","src":"기출 2021-27"},{"t":"전체 공급사슬을 관리하여 비용과 시간을 최소화하고 이익을 최대화하도록 지원","src":"기출 2021-27, 2026-31"},{"t":"정보통신기술로 공급자·제조업자·소매업자·소비자 관련 상품·정보·자금 흐름을 신속하고 효율적으로 관리하여 부가가치를 향상","src":"기출 2021-27"}]},{"머리":"SCM 도입 배경 (환경 변화)","줄":[{"t":"공급사슬 조직 간 상호 의존성 증대","src":"기출 2021-29"},{"t":"정보통신기술 발전으로 새로운 시장 등장과 경영방식 변화","src":"기출 2021-29"},{"t":"기업 간 경쟁 심화로 비용절감과 납기개선(납기준수)의 중요성 증대","src":"기출 2021-29, 2024-14"},{"t":"고객의 다양한 니즈에 맞춘 생산·납품 필요성 증대. 대량고객화 보편화","src":"기출 2021-29, 2023-28"},{"t":"물자 이동이 국내·역내에 국한되지 않고 글로벌화","src":"기출 2021-29"},{"t":"부가가치의 60~70%가 제조공정 외부 공급망에서 발생","src":"기출 2023-28"},{"t":"외부 불확실성(부품 납기·품질, 주문 납기·수요) 심화. 글로벌화로 공급망 리드타임이 길어지고 불확실해짐","src":"기출 2023-28, 2024-14"},{"t":"공급사슬 계획·운영을 지원하는 IT 솔루션 개발. 고객 요구 다양화와 제품 수명주기 단축","src":"기출 2024-14"}]},{"머리":"채찍효과 (Bullwhip Effect)","줄":[{"t":"정의: 최종소비자의 수요 정보가 공급자 방향(상류)으로 전달되는 과정에서 수요변동이 증폭되는 현상","src":"기출 2022-38, 2025-30"},{"t":"공급사슬 상류로 갈수록 수요정보가 증폭·왜곡","src":"기출 2024-14, 2025-30"},{"t":"원인: 중복·부정확한 수요예측(구성원의 독립적 수요예측)","src":"기출 2021-28, 2023-32"},{"t":"원인: 결품을 우려한 과다 주문, 공급부족에 따른 과다 주문","src":"기출 2021-28, 2023-32"},{"t":"원인: 로트(lot) 단위 또는 대단위 일괄(batch) 주문, 경제성을 고려한 일괄주문","src":"기출 2021-28, 2023-32, 2025-30"},{"t":"원인: 가격변동(판촉활동·수량할인)과 가격변동에 의한 선행구입, 구매자의 사전구매(Forward Buying)","src":"기출 2021-28, 2023-32, 2025-30"},{"t":"원인: 공급사슬 참여기업 간 정보 왜곡","src":"기출 2022-38"},{"t":"납품주기 단축·납품횟수 증대, 리드타임 단축은 채찍효과의 원인이 아님(완화 방향)","src":"기출 2021-28, 2023-32"},{"t":"완화 방법: 수요정보 공유, 파트너십 구축, 상시저가전략(EDLP)","src":"기출 2022-38, 2025-30"}]}],"함정":[{"x":"ABM(Activity Based Management)을 근간으로 하여 각 공급사슬과 접점을 이루는 부문에서 계획을 수립하는 시스템이다.","o":"출제 오답(바른 수치 미확인). SCM의 설명이 아님.","src":"기출 2021-27"},{"x":"물자의 이동이 주로 국내나 역내에서 이루어지고 있다.","o":"글로벌화로 국제 이동이 늘고 있다.","src":"기출 2021-29"},{"x":"구매자의 사전구매(Forward Buying)를 통해 채찍효과를 감소시킬 수 있다.","o":"사전구매는 채찍효과의 원인이다.","src":"기출 2022-38, 2025-30"},{"x":"공급망 하류로 갈수록 정보가 왜곡되는 현상이 심화되고 있다.","o":"공급망 상류로 갈수록 정보 왜곡이 심화된다.","src":"기출 2023-28"},{"x":"글로벌화로 인해 부품공급의 리드타임이 짧아지고 있다.","o":"리드타임이 길어지고 불확실해진다.","src":"기출 2024-14"},{"x":"참여기업들의 개별적 수요 예측을 통해 완화할 수 있다.","o":"개별 예측은 원인. 수요정보 공유·공동 예측으로 완화.","src":"기출 2025-30"},{"x":"VMI(Vendor Managed Inventory)는 소비자가 판매자의 매장 또는 물류센터의 재고를 관리하는 전략을 말한다.","o":"VMI는 공급업체가 구매자(유통업체)의 재고를 관리하는 방식.","src":"기출 2026-31, 2025-28"}]},"#11":{"묶음":[{"머리":"업계별 협업 모델","줄":[{"t":"QR(신속대응): 의류 부문에서 시작. 제조업체와 유통업체가 협력하여 적절한 시기에 적절한 양을 적절한 가격으로 제공","src":"기출 2023-25, 2023-29, 2024-29"},{"t":"ECR(효율적 소비자 대응): 식품 부문에서 시작","src":"기출 2023-25"},{"t":"EHCR: 의약품 부문에서 시작","src":"기출 2023-25"},{"t":"CRP(지속적 보충): 유통업체의 실제 판매 데이터를 토대로 제조업체가 상품을 지속적으로 공급. 별도 주문 없이 지속 보충","src":"기출 2023-29, 2024-29"},{"t":"VMI(공급업체 주도 재고관리): 공급업체가 구매자의 재고를 관리. 수요업체가 정보공유시스템으로 재고 보충 책임을 공급업체에 이전. 부품공급자가 제조업자의 생산계획을 공유하여 제조업자 재고 관리","src":"기출 2025-28, 2024-29"},{"t":"VMI는 유통업체와 제조업체가 공동으로 유통업체의 재고를 관리하는 방식이 아님(공급업체 단독 관리)","src":"기출 2023-29"},{"t":"CPFR(협업적 계획·예측·보충): 거래파트너가 특정시장 목표 사업계획을 공동 수립·공유, 판매·재고 데이터로 수요를 예측해 생산계획에 반영하고 자동 보충","src":"기출 2021-30, 2023-29"},{"t":"ECR: 제품에 대한 고객 반응을 측정해 재고관리·생산효율을 달성하는 방식(선지 형태로 출제)","src":"기출 2023-29"}]},{"머리":"크로스도킹·지연전략","줄":[{"t":"크로스도킹(Cross Docking): 입고 상품을 보관하지 않고 곧바로 소매점포에 배송. 공급업체·소매업체 차량이 약속 시간에 도착해 보관작업 없이 이동","src":"기출 2022-39, 2024-30"},{"t":"Postponement(지연): 공통모듈을 먼저 생산하고 주문 접수 후 최종 조립(전원케이블 등). 직조 후 염색(베네통)","src":"기출 2022-37, 2025-26, 2026-30"},{"t":"차별화지연(Delayed Differentiation): 제품 차별화를 최대한 뒤로 미루고 최신 수요정보를 활용해 수요의 불확실성을 감소","src":"기출 2026-31"},{"t":"리스크풀링(Risk Pooling): 공급사슬에 분포된 불확실성을 하나로 모아 시스템 전체의 불확실성을 줄임. 공통모듈 수요는 개별 제품 수요의 합이라 변동이 작아짐","src":"기출 2022-30, 2026-31"}]},{"머리":"효율적 공급사슬 vs 대응적 공급사슬","줄":[{"t":"효율적: 비용 절감(리드타임 단축보다), 공급사슬 전반 재고 최소화, 가동률 최대화가 생산운영 전략","src":"기출 2022-36, 2025-29"},{"t":"대응적: 불확실한 수요에 빠르고 유연하게 대응하는 것이 목표","src":"기출 2022-36"},{"t":"모듈화를 통한 제품 유연성·다양성 확보와 공급의 유연성 우선은 대응적 공급사슬의 성격","src":"기출 2022-36, 2025-29"}]},{"머리":"제약이론 (TOC, Goldratt)","줄":[{"t":"골드랫(E.M. Goldratt)이 제안. 제약을 찾아 집중적으로 개선. 개선 대상에는 자원·부서·인식·환경 등 제약이 되는 모든 것 포함","src":"기출 2025-13"},{"t":"지속적 개선 5단계: 제약자원 식별 → 제약자원 최대 활용 → 비제약자원을 제약자원에 종속화 → 제약자원 개선 → 개선 프로세스 반복","src":"기출 2023-12"},{"t":"DBR: Drum(제약공정의 속도), Buffer, Rope. Rope는 대열의 선두와 가장 느린 사람을 연결, 원자재·부품 재고보충이 공급업체로 전달되도록 정보교환","src":"기출 2024-15, 2022-10"},{"t":"DBR은 공정 간 자재 흐름 관리로 재고를 최소화하고 제조기간을 단축하며 제약공정을 중점 관리","src":"기출 2022-10"},{"t":"Thinking Process: 제약요인 개선으로 목표 달성 해결방안을 도출. 전체 최적화 추구","src":"기출 2022-10"},{"t":"CCPM(Critical Chain Project Management): 프로젝트 단계별 작업을 효과적으로 관리하여 기간을 단축하고 돌발상황에서도 납기수준을 높임","src":"기출 2022-10"},{"t":"산출회계(Throughput Accounting): 제약이론의 회계적 접근. 통계적 품질개선 도구가 아님","src":"기출 2025-13, 2022-10"},{"t":"재고는 판매를 위하여 재화에 투자된 자금으로 정의","src":"기출 2025-13"},{"t":"OPT(Optimized Production Technology): 정의·측정·분석·개선·관리의 DMAIC를 쓰지 않음","src":"기출 2022-10"}]},{"머리":"6시그마 (DMAIC)","줄":[{"t":"모토로라에서 처음 도입. 시그마(σ)는 표준편차. 대표 방법론 DMAIC","src":"기출 2024-16"},{"t":"2시그마 수준은 3시그마 수준보다 불량률이 큼. 6시그마 수준은 3.4PPM","src":"기출 2024-16, 보충"},{"t":"Define(정의) → Measure(측정) → Analyze(분석) → Improve(개선) → Control(관리)","src":"기출 2021-13, 2023-13, 2026-17"},{"t":"Measure: 프로세스의 현재 상태를 파악. 통계기법으로 현재 프로세스 능력을 계량화, CTQ 충족 정도 평가. 적절한 프로세스 측정방법 확인","src":"기출 2023-13, 2025-12, 2026-17"},{"t":"Analyze: 현재 수준과 목표 수준의 차이 원인 규명, 품질을 저하시키는 근본 원인 발견. 파레토도·특성요인도 활용","src":"기출 2021-13, 2025-12"},{"t":"Improve: 품질 개선 활동을 실행하고 결과를 수치화","src":"기출 2025-12"},{"t":"Control: 개선 결과를 문서화하고 개선된 프로세스가 유지되도록 통제. 점검계획 수립·실행, 지속방법 모색 및 절차 제도화","src":"기출 2025-12, 2026-17"},{"t":"새로운 품질 개선 아이디어를 환류(Feedback)하는 단계는 PDCA의 Act(Do는 실행 단계)","src":"기출 2025-12, 보충"}]},{"머리":"공급사슬 성과 관점","줄":[{"t":"공급사슬 성과지표(Cash-to-Cash, 배송성과, 주문충족 리드타임, 생산유연성)","src":"기출 2023-24"}]}],"함정":[{"x":"Drum, Buffer, Rope는 공정간 자재의 흐름 관리를 통해 재고를 최소화하고 제조 기간을 단축하는 기법으로서 비제약공정을 중점적으로 관리한다.","o":"제약공정을 중점 관리한다.","src":"기출 2022-10"},{"x":"Thinking Process는 제약요인을 개선하여 목표를 달성하는 구체적 해결방안을 도출하는 기법으로서 부분 최적화를 추구한다.","o":"전체 최적화를 추구한다.","src":"기출 2022-10"},{"x":"Throughput Account는 통계적 기법을 활용한 품질개선 도구이다.","o":"산출회계는 제약이론의 회계 기법이고, 통계적 품질개선 도구는 6시그마.","src":"기출 2022-10, 2025-13"},{"x":"Optimized Production Technology는 정의, 측정, 분석, 개선, 관리의 DMAIC 프로세스를 활용한다.","o":"DMAIC는 6시그마.","src":"기출 2022-10"},{"x":"6시그마 수준은 불량률 4.3 PPM을 의미한다.","o":"6시그마 수준은 3.4PPM(보충).","src":"기출 2024-16, 보충"},{"x":"Do는 새로운 품질 개선 아이디어를 환류(Feedback)하는 단계이다.","o":"환류 단계는 Act. Do는 실행.","src":"기출 2025-12"},{"x":"효율적 공급사슬은 모듈화를 통한 제품 유연성 확보에 초점을 둔다.","o":"모듈화·유연성 확보는 대응적 공급사슬.","src":"기출 2022-36, 2025-29"},{"x":"대응적 공급사슬은 리드타임 단축보다 비용최소화에 초점을 둔다.","o":"대응적은 리드타임 단축에 초점. 비용최소화는 효율적.","src":"기출 2022-36"},{"x":"공급자 선정과정에서 비용보다는 공급의 유연성을 우선적으로 고려한다. (효율적 공급사슬)","o":"효율적은 비용을 우선. 유연성 우선은 대응적.","src":"기출 2025-29"},{"x":"VMI(Vendor-Managed Inventory): 유통업체와 제조업체가 실시간 정보공유를 통해 공동으로 유통업체의 재고를 관리하는 방식","o":"VMI는 공급업체가 구매자 재고를 관리.","src":"기출 2023-29"}]},"#12":{"묶음":[{"머리":"3자물류 정의","줄":[{"t":"제3자물류: 화주가 대통령령으로 정하는 특수관계에 있지 아니한 물류기업에 물류활동의 일부 또는 전부를 위탁하는 것","src":"물류정책기본법 제2조 제1항 제10호"},{"t":"3자물류: 화주와 물류업체 간 전략적·장기적 협력관계. 운송·보관 포함 물류 프로세스 대부분을 수행","src":"기출 2025-11"}]},{"머리":"4자물류(4PL)","줄":[{"t":"3PL, 물류컨설팅 업체, IT 업체 등이 결합한 형태. 3자물류에 IT·기술·전략적 컨설팅 추가","src":"기출 2021-11, 2022-25, 2023-35, 2024-10, 2025-11, 2026-12"},{"t":"공급사슬 전체의 관리·운영 대상. 포괄적 SCM 서비스를 위한 통합서비스로 공급사슬 전반 최적화","src":"기출 2021-11, 2023-35, 2024-10, 2026-12"},{"t":"합작투자 또는 장기 제휴 형태. 참여 업체 공통의 목표설정과 이익분배","src":"기출 2021-11, 2022-25, 2023-35, 2024-10"},{"t":"다양한 기업이 파트너로 참여하는 혼합조직","src":"기출 2021-11, 2023-35"},{"t":"목적: 수입증대, 운영비용 감소, 운전자본 감소, 고정자본 감소. 사이클 타임 단축","src":"기출 2024-10, 2022-25"},{"t":"기존 물류업체의 한계를 극복하고 지속적 개선효과 창출","src":"기출 2024-10"},{"t":"기능별 서비스와 상하계약관계는 4PL의 특징이 아님","src":"기출 2021-11"},{"t":"모회사 유휴인력의 물류자회사 파견은 4PL의 특징이 아님","src":"기출 2026-12"}]},{"머리":"외주물류(아웃소싱)와 3자물류 비교","줄":[{"t":"외주물류: 운영 측면 원가절감 목표, 기능별 서비스(수송·보관) 수행, 단기적 관계, 중간관리층 의사결정·수의계약 중심","src":"기출 2023-30, 2026-13"},{"t":"3자물류: 원가절감과 경쟁우위·물류전략 지원·고객서비스 향상, 종합물류 지향, 중장기 협력, 최고경영층 의사결정·경쟁계약 중심","src":"기출 2023-30, 2026-13"},{"t":"외주물류는 수동적 서비스, 3자물류는 능동적·적극적 서비스","src":"기출 2026-13"}]},{"머리":"아웃소싱의 장단점","줄":[{"t":"제조업체 단점: 고객 불만에 신속한 대처가 어렵다. 물류정보 유출 가능. 내부 전문가 상실과 사내 전문지식 축적 곤란","src":"기출 2024-12, 2025-11"},{"t":"제조업체 장점: 물류거점 자본투입 최소화, 전문 물류업체 인프라의 전략적 활용","src":"기출 2024-12"},{"t":"물류업체 장점: 규모의 경제를 통한 효율 증대","src":"기출 2024-12"}]}],"함정":[{"x":"수입증대, 운영비용 감소, 운전자본 확대, 고정자본 확대를 목적으로 한다. (4PL)","o":"운전자본·고정자본은 감소를 목적으로 한다.","src":"기출 2024-10"},{"x":"사이클 타임과 운전자본의 증대 (4PL)","o":"사이클 타임과 운전자본의 감소.","src":"기출 2022-25"},{"x":"기업과 고객 간의 거래(B2C) 보다는 기업과 기업 간의 거래(B2B)에 집중한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-35"},{"x":"제조업체는 물류거점에 대한 자본투입을 최대화하고 전문 물류업체의 인프라를 전략적으로 활용할 수 있다.","o":"자본투입을 최소화한다.","src":"기출 2024-12"},{"x":"자가물류 방식에 비해 화주의 정보 유출 우려가 적다.","o":"3PL은 정보 유출 우려가 있다.","src":"기출 2025-11"},{"x":"4PL: 기능별 서비스와 상하계약관계","o":"4PL은 공동 목표·이익분배·장기 제휴이며 기능별 서비스·상하계약은 3PL 성격.","src":"기출 2021-11"},{"x":"외주물류는 중장기적 협력 관계를 기반으로 이루어지는 반면, 3자물류는 단기적 관계를 기반으로 운영된다.","o":"외주물류는 단기적, 3자물류는 중장기적 관계.","src":"기출 2023-30, 2026-13"},{"x":"외주물류는 주로 최고경영층의 의사결정에 따라 경쟁계약의 형태로 진행되는 반면, 3자물류는 중간관리층의 의사결정에 따라 수의계약 형태로 주로 진행된다.","o":"외주물류가 중간관리층·수의계약, 3자물류가 최고경영층·경쟁계약.","src":"기출 2023-30"},{"x":"외주물류는 주로 능동적·적극적으로 서비스를 제공하는 반면, 3자물류는 주로 수동적 서비스를 제공한다.","o":"외주물류가 수동적, 3자물류가 능동적.","src":"기출 2026-13"},{"x":"서비스 범위 측면에서 외주물류는 종합물류 서비스를 지향하는 반면, 3자물류는 기능별 서비스를 지향한다.","o":"외주물류가 기능별, 3자물류가 종합물류.","src":"기출 2026-13"}]},"#13":{"묶음":[{"머리":"수요예측 기법","줄":[{"t":"지수평활법: 단기 수요예측에 유용, 최근 수요에 많은 가중치. 오랜 기간 실적이 필요 없고 데이터 처리 시간이 적음","src":"기출 2022-23"},{"t":"회귀분석법(인과형): 수요에 영향을 미치는 독립변수를 파악하고 독립변수와 종속변수 간 함수관계를 통계적으로 추정해 미래 수요를 예측","src":"기출 2023-8"},{"t":"패널조사법(패널동의법): 다수의 의견이 소수보다 우월하다는 전제로 경영자·생산자·소비자·판매자 등이 참여하는 위원회에서 자유로운 의견으로 수요 예측","src":"기출 2026-15"},{"t":"정성적 기법 보기: 시장조사법, 델파이법, 판매원이용법, 패널조사법, 역사적 자료 유추법, 수명주기예측법","src":"기출 2022-23, 2026-15, 2023-8"},{"t":"정량적 기법 보기: 지수평활법, 가중이동평균법, 회귀분석법","src":"기출 2023-8, 2022-23"},{"t":"델파이법: 전문가들의 익명 설문을 반복해 의견을 수렴하는 정성적 기법","src":"보충"}]},{"머리":"브레인스토밍 진행원칙","줄":[{"t":"자유분방, 비판금지, 의견편승(타인 의견 결합·발전), 전원참여. 질보다 양","src":"기출 2026-14, 보충"}]},{"머리":"자재관리 시스템","줄":[{"t":"MRP(자재소요계획): 주일정계획(MPS) 수립 후 작업완료일로부터 역산하여 일정 산출. MRP-II로 확장되고 ERP로 발전","src":"기출 2026-22, 2024-22"},{"t":"JIT: 최소 재고유지를 통한 낭비제거 목표의 적시생산시스템. 칸반(Kanban) 시스템으로도 불림. 도요타 개발","src":"기출 2024-22, 2026-22"},{"t":"JIT-II: Bose사가 개발. 공급회사 영업과 발주회사 구매를 묶어 하나의 가상기업으로 간주, 공급회사 전문요원이 구매·납품 업무 대행","src":"기출 2022-14, 2024-22"},{"t":"MRP는 도요타가 개발한 시스템이 아님. JIT-II도 도요타가 개발한 것이 아님","src":"기출 2026-22, 2024-22"}]},{"머리":"계산: EOQ·재고 (공식)","줄":[{"t":"EOQ = √(2 × 연간수요 × 1회 주문비 ÷ 단위당 연간 재고유지비). 풀이 순서: D, S, H 확인 → 대입 → 제곱근","src":"보충"},{"t":"연간 총비용 = 주문비(D÷Q×S) + 재고유지비(Q÷2×H). EOQ에서 두 비용이 같음","src":"보충"}]}],"함정":[{"x":"양보다 질 (브레인스토밍 진행원칙)","o":"질보다 양을 중시한다.","src":"기출 2026-14"},{"x":"JIT-II는 일본 도요타 자동차가 개발한 시스템이다.","o":"JIT-II는 Bose사가 개발.","src":"기출 2024-22"},{"x":"MRP는 일본 도요타 자동차가 개발한 시스템이다.","o":"도요타가 개발한 것은 JIT.","src":"기출 2026-22"}]},"#14":{"묶음":[{"머리":"마케팅과 물류","줄":[{"t":"마케팅믹스(4P): 제품(Product)·가격(Price)·유통(Place)·촉진(Promotion)","src":"기출 2024-8, 2026-8"},{"t":"물류는 4P 중 유통(Place, 유통채널)과 관련이 깊음","src":"기출 2023-9, 2024-8, 2025-6"},{"t":"물류역량이 강한 기업일수록 수요의 창출·조절에 유리","src":"기출 2023-9, 2026-8"},{"t":"물류는 마케팅뿐 아니라 생산관리 측면까지 확대. 포괄적 마케팅에 포함되며 물류 자체의 마케팅 활동도 가능","src":"기출 2023-9"},{"t":"물류관리는 마케팅믹스와 통합적 관점에서 추진","src":"기출 2026-8"},{"t":"마케팅은 고객 욕구 충족을 목표로 한 고객만족의 실현이 주요 목표","src":"기출 2026-8"},{"t":"탁월한 고객서비스를 제공하는 마케팅은 고객만족을 증대","src":"기출 2024-8"},{"t":"물류와 영업 업무를 각각 전담부서가 수행하면 전문화로 핵심역량 강화. 공동화·통합화·대량화에 의한 규모의 경제로 물류비 절감, 차량 적재효율 향상, 대규모 물류시설 기계화·자동화","src":"기출 2023-10"}]},{"머리":"유통경로 시스템","줄":[{"t":"전통적 유통경로: 자체적으로 마케팅 기능을 수행하는 독립적 단위로 구성. 구성원 간 결속력은 약하나 유연성이 높음","src":"기출 2023-17"},{"t":"수직적 마케팅 시스템(VMS): 한 주체가 계획된 프로그램으로 경로구성원을 전문적으로 관리·통제. 폐쇄적이어서 신규 진입이 어려움","src":"기출 2025-18, 2023-17"},{"t":"기업형 VMS: 한 경로구성원이 다른 구성원을 법적으로 소유·관리. 특정 유통경로가 다른 경로를 소유·통제","src":"기출 2023-17, 2025-18"},{"t":"계약형 VMS: 경로구성원이 수행할 유통기능을 계약으로 합의. 도소매기관 지원형 연쇄점, 소매기관 협동조합, 프랜차이즈","src":"기출 2023-17, 2025-18"},{"t":"관리형 VMS: 규모·영향력이 큰 구성원이 다른 구성원을 관리(소유·계약 없이)","src":"보충"},{"t":"수직적 통합 정도: 기업형 > 계약형 > 관리형. 경로구성원 통제력도 기업형이 관리형보다 강함","src":"기출 2024-21, 2025-18"},{"t":"전통적 경로보다 전후방 통합 정도가 높고, 구성원 각자의 이익극대화 추구 현상이 줄어듦","src":"기출 2024-21"}]},{"머리":"도매기관 유형","줄":[{"t":"도매기관 유형: 상인 도매기관(merchant), 대리 도매기관(agent), 제조업자 도매기관(manufacturer)","src":"기출 2025-22"},{"t":"상인 도매기관: 취급 상품의 소유권을 보유하며 제조업자·소매상과 관련없는 독립 사업자","src":"기출 2026-24"},{"t":"라스트마일·옴니채널 도매기관은 도매기관 유형이 아님","src":"기출 2025-22, 2026-24"},{"t":"Broker(브로커): 구매자·판매자 간 거래 중개가 주된 기능이며 제품 소유권은 없음","src":"기출 2024-23"},{"t":"한정서비스 도매상: 현금거래 도매상(Cash and Carry), 트럭 도매상(Truck Jobber), 직송 도매상(Drop Shipper), 진열 도매상(Rack Jobber)","src":"기출 2022-27, 2024-23"},{"t":"전문품 도매상(Specialty Wholesaler)은 한정서비스 도매상이 아님(완전서비스 도매상)","src":"기출 2022-27"}]},{"머리":"소매업태","줄":[{"t":"카테고리 킬러(Category Killer): 할인형 대규모 전문점. 특정 상품군을 전문 취급하고 풍부한 구색과 저렴한 가격. 토이저러스·오피스디포. 대량구매·대량판매·낮은 운영비","src":"기출 2022-29, 2024-23, 2025-21"},{"t":"팩토리 아웃렛: 상설할인매장. 제조업체의 잉여상품·단절상품·재고상품 취급","src":"기출 2024-23"},{"t":"슈퍼마켓: 식료품·일용품 중심, 셀프서비스","src":"기출 2024-23"},{"t":"소매 보기: 백화점, 대중양판점(GMS), 하이퍼마켓, 슈퍼센터","src":"기출 2022-29, 2025-21"}]},{"머리":"CRM","줄":[{"t":"CRM의 목적: 고객 확보·유지 및 고객 충성도 증대","src":"기출 2026-29"},{"t":"마케팅 분야에서 상품관리·프로모션관리·채널관리 영역에 사용","src":"기출 2026-29"},{"t":"도입 효과: 우량고객·신규고객·교차판매 증가로 수익성 향상. 고객 유지·획득비용 감소, 타겟 마케팅으로 고객당 영업비용 절감","src":"기출 2026-29"},{"t":"자재공급에서 최종소비까지 전체 공급사슬의 고객 대응성을 높이는 개념은 SCM이며 CRM이 아님","src":"기출 2026-29"}]}],"함정":[{"x":"물류와 마케팅 기능이 상호작용하는 분야는 하역관리와 설비관리 등이 있다.","o":"출제 오답(바른 수치 미확인). 마케팅과 물류의 상호작용은 재고·운송·창고·주문처리·고객서비스 쪽(추정).","src":"기출 2023-9, 보충(추정)"},{"x":"영업소와 고객 간 직배송이 확대되므로 고객서비스가 향상된다.","o":"출제 오답(바른 수치 미확인). 영업소 통합·집약으로 직배송은 줄고 거점 중심으로 바뀜(추정).","src":"기출 2023-10, 보충(추정)"},{"x":"수직적 유통경로 시스템은 신규 구성원의 진입이 상대적으로 용이한 개방형 네트워크이다.","o":"폐쇄형 네트워크로 신규 진입이 어렵다.","src":"기출 2023-17"},{"x":"기업형 VMS의 대표적 유형은 프랜차이즈 시스템이다.","o":"프랜차이즈는 계약형 VMS.","src":"기출 2024-21"},{"x":"경로구성원에 대한 통제력은 관리형 VMS가 기업형 VMS보다 더 강하다.","o":"기업형 VMS의 통제력이 더 강하다.","src":"기출 2025-18"},{"x":"Rack Jobber는 완전서비스 도매상(Full-service wholesaler)에 속한다.","o":"Rack Jobber는 한정서비스 도매상.","src":"기출 2024-23"},{"x":"물류는 마케팅믹스 중에서 촉진과 가장 밀접한 관계가 있다.","o":"유통(Place)과 가장 밀접.","src":"기출 2026-8"},{"x":"CRM은 자재공급에서 최종소비까지 전체 공급사슬의 고객 대응성을 높임으로써, 고객의 편의를 증진하면서도 전체 공급사슬이 최소비용으로 운용될 수 있도록 관리하는 기법과 개념을 의미한다.","o":"그 설명은 SCM. CRM은 고객 확보·유지 중심.","src":"기출 2026-29"}]},"#15":{"묶음":[{"머리":"e-조달","줄":[{"t":"장점: 운영비용 절감, 조달효율성 개선, 조달가격 절감, 문서처리 비용 감소","src":"기출 2021-19, 2025-20"},{"t":"장점: 구매업무 처리시간 절감, 프로세스 자동화로 구매비용 절감, 실시간 정보로 재고·예산 관리","src":"기출 2025-20"},{"t":"구매자와 판매자 간 밀접한 관계 구축은 e-조달의 장점으로 보지 않음. 신용정보·거래정보 유출 위험은 존재","src":"기출 2021-19, 2025-20"}]},{"머리":"공급업체 선정 방법","줄":[{"t":"협의에 의한 방법: 다수 공급업체의 제안서를 받아 평가한 뒤 협상으로 가장 유리한 업체와 계약","src":"기출 2021-20"},{"t":"기타 방법: 입찰(일반경쟁), 제한경쟁, 지명경쟁, 수의계약","src":"기출 2021-20"},{"t":"제한경쟁은 자격 제한, 지명경쟁은 특정 업체 지명, 수의계약은 특정 업체와 임의 계약","src":"보충"}]},{"머리":"집중구매","줄":[{"t":"장점: 구입절차 표준화로 구매비용 절감, 대량구매로 가격·거래조건 유리, 공통자재 표준화·단순화, 수입 등 복잡한 구매에 유리","src":"기출 2021-21"},{"t":"단점: 긴급수요 발생 시 대응에 불리","src":"기출 2021-21"}]},{"머리":"구매 전략과 공급업체 관계","줄":[{"t":"구매전략: 총소유비용(TCO) 절감 중시. 공급자 수를 줄이는 물량통합과 공급자와의 운영통합","src":"기출 2023-16"},{"t":"JIT 구매: 적기에 필요한 품목을 필요한 양만큼 확보. 공급자 정보공유 필요성 증대. 품질 향상을 위해 구매자가 공급자 활동이 안정적으로 수행되도록 협력","src":"기출 2023-16"},{"t":"장기 협력 공급업체 특징: 건전한 재무상태, 유연한 공급능력, 안정적(신뢰있는) 노사관계, 정보시스템의 높은 상호운용성","src":"기출 2025-19, 2026-23"},{"t":"품질·원가의 높은 변동성은 장기 협력 공급업체의 특징이 아님","src":"기출 2025-19, 2026-23"}]}],"함정":[{"x":"긴급수요 발생 시 대응에 유리하다. (집중구매)","o":"긴급수요 대응에는 불리하다.","src":"기출 2021-21"},{"x":"최근에는 총소유비용 절감보다 구매단가 인하를 위한 협상 전략이 더 중요해졌다.","o":"구매단가 인하 협상보다 총소유비용(TCO) 절감이 중요해졌다.","src":"기출 2023-16"},{"x":"e-조달: 구매자와 판매자 간에 밀접한 관계가 구축된다.","o":"e-조달의 장점으로 보기 어렵다.","src":"기출 2021-19"},{"x":"e-조달: 신용정보 및 거래정보의 유출 위험이 없다.","o":"정보 유출 위험이 있다.","src":"기출 2025-20"}]},"#16":{"묶음":[{"머리":"정의와 대상","줄":[{"t":"물류표준화: 원활한 물류를 위해 ①시설·장비의 종류·형상·치수·구조 ②포장의 종류·형상·치수·구조·방법 ③물류용어·물류회계·물류 관련 전자문서 등을 물류표준으로 통일하고 단순화","src":"물류정책기본법 제2조 제1항 제7호"},{"t":"물류표준: 산업표준화법에 따른 한국산업표준(KS) 중 물류활동과 관련된 것","src":"물류정책기본법 제2조 제1항 제6호"},{"t":"표준화 대상: 수송, 보관, 포장, 물류정보. 물류조직은 대상이 아님","src":"기출 2021-32"},{"t":"목적: 단위화물체계 보급, 물류기기와의 연계성 향상, 물류비 절감, 물류활동 효율화. 납품주기 단축·납품횟수 증대는 목적이 아님","src":"기출 2024-31, 2022-8"},{"t":"운송·보관·하역·포장 정보의 일관처리로 효율성 제고","src":"기출 2022-8"},{"t":"자원·에너지 절감 효과: 재료의 경량화","src":"기출 2021-33"},{"t":"하드웨어 표준화: 파렛트, 내수용 컨테이너, 물류시설 및 장비, 적재함, 보관랙","src":"기출 2022-6, 2026-34"},{"t":"소프트웨어 표준화: 포장치수, 물류용어, 거래단위","src":"기출 2022-6, 2026-34"}]},{"머리":"물류모듈","줄":[{"t":"물류모듈: 물류시설·장비의 규격·치수가 일정한 배수 또는 분할 관계로 조합된 집합체로, 표준화를 위한 기준치수","src":"기출 2022-8, 2024-33, 2025-33"},{"t":"Unit Load 치수: NULS(Net Unit Load Size)와 PVS(Plan View Size)","src":"기출 2022-8, 2024-33"},{"t":"배수치수 모듈: 1,140mm×1,140mm Unit Load Size를 기준으로 최대 허용공차 −40mm를 인정하는 Plan View Unit Load Size를 기본단위로 함","src":"기출 2021-34, 2022-8"},{"t":"물류모듈은 포장 치수와 독립적으로 정하는 것이 아니라 포장 치수를 물류모듈에 맞춤","src":"기출 2025-33"}]},{"머리":"파렛트 표준과 적재효율","줄":[{"t":"T-11형 표준 파렛트: 1,100mm × 1,100mm","src":"기출 2021-31, 2024-33"},{"t":"적재효율 = (1단에 적재된 박스 면적 합) ÷ 파렛트 면적 × 100","src":"기출 2021-31"},{"t":"풀이 순서: 박스 면적 × 적재수 → 파렛트 면적(1,100×1,100)으로 나눔 → 가장 작은 값이 효율 최저","src":"기출 2021-31"},{"t":"예: 733×366×4 ÷ (1,100×1,100) ≈ 88.7%로 보기 중 최저. 1,100×275 박스 4개는 100%","src":"기출 2021-31, 2024-33"},{"t":"랙 보관량 풀이: 가용 높이 = 랙 높이 − 파렛트 높이 → 단수 = 가용 높이 ÷ 박스 높이(내림) → 1단 적재수 × 단수","src":"기출 2026-32"},{"t":"예: (2,000−144)÷245=7.57 → 7단. 1,100×1,100에 550×275 박스는 2×4=8개 → 8×7=56개","src":"기출 2026-32"}]},{"머리":"파렛트 적재 방식","줄":[{"t":"교대배열(교호열) 쌓기: 홀수단은 물품을 모두 같은 방향으로 정돈, 짝수단은 90도 회전해 교대로 겹쳐 쌓음. 화물이 갈라질 염려가 적고 정방형 파렛트에 적합. 적재 시간이 길게 소요","src":"기출 2022-9, 2026-37"},{"t":"적재 형태 보기: 블록(Block), 벽돌(Brick), 풍차(Pinwheel), 스플릿(Split), 교대배열(Row)","src":"기출 2022-9, 2026-37"}]},{"머리":"단위적재시스템(ULS)","줄":[{"t":"ULS: 화물을 중량 또는 체적으로 일정하게 단위화하여 하역·수송·보관을 기계화·합리화하는 시스템","src":"기출 2023-27, 2025-32, 2026-33"},{"t":"ULS 도입 시 거래단위 표준화 필요. 포장비용 절감, 적재효율 향상","src":"기출 2025-32"},{"t":"운송·보관·하역 등 작업의 일관화·기계화. 파렛트·하역장비·적재함·보관설비 등의 표준화 필요","src":"기출 2026-33"},{"t":"Unit Load가 생성된 후 해당 상품의 운반·하역 실시. 파렛트 적재 화물의 붕괴·훼손 가능성 고려","src":"기출 2025-32, 2026-33"},{"t":"서비스 수준을 높이려고 고객이 지정한 규격의 파렛트를 쓰는 것은 ULS 취지에 맞지 않음(표준 파렛트 사용)","src":"기출 2025-32"}]},{"머리":"포장 표준화","줄":[{"t":"포장표준화 4요소: 치수·강도·재료·기법 표준화(관리의 표준화를 추가하기도 함)","src":"기출 2023-22"},{"t":"포장 치수는 파렛트·컨테이너 치수에 정합. 포장이 표준화되어야 기계화·자동화·파렛트화·컨테이너화 용이. 포장비·포장재료비·포장작업비 절감","src":"기출 2023-22"},{"t":"포장의 모듈화: 하역·보관·운송 합리화를 위해 제품에 최적화된 포장치수를 선택해 포장의 단위화를 가능하게 함","src":"기출 2024-32"}]}],"함정":[{"x":"배수치수 모듈은 1,140mm × 1,140mm Unit Load Size를 기준으로 하고, 최대 허용공차 -80mm를 인정하고 있는 Plan View Unit Load Size를 기본단위로 하고 있다.","o":"최대 허용공차는 −40mm.","src":"기출 2022-8"},{"x":"T-11형 파렛트는 11톤 트럭에 최대 12매가 적재되도록 물류모듈 배수관계가 정립되어 있다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-33"},{"x":"치수표준화는 비용절감효과가 빠르게 나타나지만 강도표준화는 그 효과가 나타나기까지 오랜 시간이 걸린다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-22"},{"x":"서비스 수준을 높이기 위해 고객이 지정한 규격의 파렛트를 구비하여 활용한다.","o":"표준 파렛트를 사용한다.","src":"기출 2025-32"},{"x":"주문시기 및 주문량 표준화를 통한 물동량 평준화가 필요하다.","o":"출제 오답(바른 수치 미확인). ULS는 거래단위·파렛트 등을 표준화한다.","src":"기출 2026-33"},{"x":"한국산업표준(KS)으로 제정된 수송포장계열치수는 1,140 mm를 정수로 나눈 배수모듈 시스템이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-33"},{"x":"Unit Load의 최대허용치수(Maximum Plan View Size)는 1,100 mm × 1,100 mm이다.","o":"출제 오답(바른 수치 미확인). 배수모듈 기준은 1,140×1,140.","src":"기출 2025-33"},{"x":"상품성을 높이기 위해서 상품의 포장 치수를 물류 모듈과 독립적으로 결정하는 것이 바람직하다.","o":"포장 치수를 물류모듈에 맞춘다.","src":"기출 2025-33"},{"x":"적재함 폭이 2,340 mm인 8 톤 트럭에는 일관수송용 T-1 표준파렛트 16 매가 적재된다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-33"}]},"#17":{"묶음":[{"머리":"정의와 대상","줄":[{"t":"물류공동화: 물류기업이나 화주기업이 물류활동의 효율성을 높이기 위해 시설·장비·인력·조직·정보망 등을 공동으로 이용하는 것","src":"물류정책기본법 제2조 제1항 제5호"},{"t":"공동화 추진 대상: 수·배송, 보관, 포장, 물류정보 기능. 제품개발 기능은 대상 아님","src":"기출 2026-35"}]},{"머리":"필요성","줄":[{"t":"다빈도 소량 수·배송 증가(소비자 욕구 다양화, 전자상거래)","src":"기출 2021-36, 2023-26, 2025-36"},{"t":"주문단위 소량화, 물류비용 증가, 배송차량 적재효율 저하","src":"기출 2021-36"},{"t":"화물량 증가에 따른 도로혼잡·환경오염 문제, 새로운 시설·설비 투자 위험부담 감소 필요","src":"기출 2023-26"},{"t":"소비자의 물류서비스 차별화 요구 증가는 공동화의 필요성 설명이 아님","src":"기출 2023-26"}]},{"머리":"기대 효과","줄":[{"t":"물류비용 절감, 차량 적재율 향상과 공차율 감소, 물류업무 인원 감소, 물류작업 생산성 향상","src":"기출 2022-2, 2023-19"},{"t":"교통혼잡 완화, 환경오염 방지, 물가 상승 억제 기여","src":"기출 2022-2, 2023-19, 2025-36"},{"t":"화주기업: 규모의 경제로 단위당 물류비 절감, 고객 서비스 수준 향상, 핵심역량 강화","src":"기출 2025-34, 2026-36"},{"t":"운수업자: 물류정보시스템 구축 촉진, 화물 대량화에 의한 운송효율 향상","src":"기출 2025-34, 2026-36"},{"t":"물류인력 고용증대는 기대 효과가 아님","src":"기출 2023-19"}]},{"머리":"전제 조건","줄":[{"t":"대상 기업 간 배송조건의 유사성, 물류업무의 유사성","src":"기출 2023-21, 2026-38"},{"t":"공동수배송을 주도할 중심업체(간사 역할 회사) 존재","src":"기출 2023-21, 2024-34, 2026-38"},{"t":"기업 간 공동수배송에 대한 이해 일치, 공동의 목표","src":"기출 2022-4, 2023-21, 2024-34, 2026-38"},{"t":"일정 지역 내 참여 복수 기업(화주) 존재. 배송처 분포밀도가 높으면 적재율 증가로 비용 절감","src":"기출 2023-21, 2024-34, 2022-4"},{"t":"물류표준화 선행(화물 규격, 포장, 파렛트 규격). 표준물류심벌·통일 전표·교환 가능 파렛트","src":"기출 2021-35, 2022-4, 2024-34"},{"t":"화물형태가 규격화된 품목이 적합. 비규격품·목재·골재·위험물은 효과가 낮음","src":"기출 2022-4, 2023-21, 2024-34"},{"t":"자사 정보시스템·각종 규격·서비스를 공유(시스템 개방 포함). 운영규칙과 비용산정 기준 수립·체계화","src":"기출 2021-35, 2022-4, 2026-38"}]},{"머리":"문제점","줄":[{"t":"새로운 공동배송센터·정보시스템 투자 위험부담","src":"기출 2024-35"},{"t":"참여기업의 기밀유지 문제 발생 가능성이 높아짐","src":"기출 2024-35, 2026-36"},{"t":"포장·전표·용기 표준화가 어려우면 효율 저하. 이해 조정·의사소통·의사결정 지연","src":"기출 2024-35"},{"t":"차별화된 배송서비스를 경쟁전략으로 둔 기업은 참여를 기피. 긴급 수요 대응 능력 저하로 기피하는 경우","src":"기출 2025-36"}]},{"머리":"공동 수·배송 유형","줄":[{"t":"배송공동형: 배송만 공동화. 화물거점시설까지의 공동화는 포함하지 않음","src":"기출 2021-37"},{"t":"집배송공동형: 배송센터 배송뿐 아니라 화물의 보관·집하까지 공동화(주문처리 제외)","src":"기출 2022-3, 2024-36, 2021-37"},{"t":"집배송공동형 중 특정화주공동형: 동일 화주가 조합·연합회를 만들어 공동화","src":"기출 2021-37, 2024-36"},{"t":"집배송공동형 중 운송업자공동형: 다수 운송사업자가 불특정 다수 화주의 집배송을 공동화(지역 분담 집화·배송)","src":"기출 2021-37, 2024-36, 2025-35"},{"t":"노선집하공동형(노선집화): 노선업자가 화물을 공동 집화하여 각지로 발송","src":"기출 2021-37, 2022-3"},{"t":"납품대행형: 운송업자가 화주를 대신하여 납입선에 납품을 대행","src":"기출 2021-37, 2022-3"},{"t":"공동수주·공동배송형: 공동으로 수주하고 공동 배송","src":"기출 2022-3"}]}],"함정":[{"x":"납품대행형은 화주가 납입선에 대행으로 납품하는 것이다.","o":"납품대행형은 운송업자가 화주를 대신해 납입선에 납품하는 것(추정).","src":"기출 2021-37, 보충(추정)"},{"x":"자사의 물류시스템과 타사의 물류시스템을 연계시켜 하나의 시스템으로 운영해야 하지만 회사 보안을 위해 시스템 개방은 포함하지 않는다.","o":"시스템 개방(정보 공유)이 포함되어야 한다.","src":"기출 2021-35"},{"x":"차량 적재율과 공차율이 증가한다.","o":"적재율은 증가하고 공차율은 감소한다.","src":"기출 2022-2"},{"x":"자사의 정보시스템, 각종 규격 및 서비스에 대한 공유를 지양해야 한다.","o":"공유가 필요하다.","src":"기출 2022-4"},{"x":"화물형태가 일정하지 않은 비규격품, 목재, 골재, 위험물 등은 공동배송에 효과가 높다.","o":"비규격품은 효과가 낮고 규격화된 품목이 적합.","src":"기출 2024-34"},{"x":"참여기업의 기밀유지 문제가 발생할 가능성이 낮아진다.","o":"기밀유지 문제 발생 가능성이 높다.","src":"기출 2024-35"},{"x":"동일 지역 내에 공동물류센터가 없으면 공동수배송을 실시할 수 없다.","o":"출제 오답(바른 수치 미확인). 공동물류센터 유무가 필수 조건은 아님.","src":"기출 2025-36"},{"x":"제품 매출이나 거래조건 등 화주의 영업기밀을 보호하는 기능이 강화될 수 있다.","o":"영업기밀 노출 위험이 있다.","src":"기출 2026-36"},{"x":"제품특성을 반영하여 화주별로 최적의 파렛트 규격을 정해야 한다.","o":"파렛트 규격은 표준화한다.","src":"기출 2026-38"}]},"#18":{"묶음":[{"머리":"역물류","줄":[{"t":"역물류: 순물류와 반대 방향의 물류 흐름. 반품물류·폐기물류·회수물류 포함","src":"기출 2025-1, 2023-31, 2022-22"},{"t":"소비단계의 불량품·반품·폐기 제품을 회수해 상태별로 분류 후 재활용하는 과정의 물류활동 포함","src":"기출 2022-33"},{"t":"역물류는 수작업이 많아 자동화가 어려움","src":"기출 2022-33"},{"t":"회수물류: 파렛트·컨테이너 등 물류용기의 재활용을 위한 회수","src":"기출 2025-1"},{"t":"사용 완료된 일회용 소모성 자재는 회수물류가 아니라 폐기물류 대상","src":"기출 2025-1"},{"t":"온라인 쇼핑 증가로 반품물류 중요성 증가","src":"기출 2025-1"}]},{"머리":"녹색물류","줄":[{"t":"녹색물류는 순물류(Forward Logistics)와 역물류를 포괄","src":"기출 2025-38"},{"t":"기후변화 영향으로 자원재생형 녹색물류 중요. 운송 온실가스 저감대책 수립·실행이 녹색물류활동","src":"기출 2025-38"},{"t":"녹색물류인증: 기업의 환경부하 저감사업 실적을 평가해 인증","src":"기출 2025-38"},{"t":"수배송 공동화 등 공동 물류활동 확산은 환경오염을 줄임","src":"기출 2025-38"},{"t":"관련 제도: 저탄소녹색성장기본법, 온실가스·에너지 목표관리제, 탄소배출권거래제, 생산자책임재활용제도(EPR)","src":"기출 2021-39"},{"t":"제조물책임법(PL)은 녹색물류 관련 제도가 아님","src":"기출 2021-39"},{"t":"EPR(생산자책임재활용): 효율적 자원이용, 폐기물 발생 감소, 재활용 촉진","src":"기출 2024-39"},{"t":"ISO 14000 시리즈가 환경경영 기본방침. ISO 9000은 품질경영","src":"기출 2024-39, 보충"},{"t":"교토의정서(1997) 6대 온실가스: 이산화탄소(CO2)·메탄(CH4)·아산화질소(N2O)·수소불화탄소(HFCs)·과불화탄소(PFCs)·육불화황(SF6)","src":"기출 2024-39"},{"t":"우리나라는 2050 탄소중립 선언, 2030년까지 국가 온실가스 감축목표를 2018년 대비 40%로 설정","src":"기출 2024-39"},{"t":"국내 육상운송부문 이산화탄소 절감 대책으로 친환경 운송수단 전환","src":"기출 2024-39"}]},{"머리":"계산: 연비법 CO2 배출량","줄":[{"t":"공식: CO2 배출량(kg) = 주행거리(km) ÷ 연비(km/L) × 배출계수(kg/L)","src":"기출 2022-31, 2023-34"},{"t":"풀이 순서: 개선 전·후 연료사용량 계산(거리÷연비) → 배출계수 곱함 → 차이가 감소량. 목표 감축 문제는 목표 배출량을 식에 넣어 연비 역산","src":"기출 2022-31, 2023-34, 2024-38, 2026-39"},{"t":"예: 100,000km, 연비 4→5, 계수 0.002 → 50kg → 40kg, 감소 10kg","src":"기출 2022-31"},{"t":"예: 150,000km, 연비 5, 감축 10kg → 현재 60kg → 목표 50kg → 연비 6.0","src":"기출 2023-34"},{"t":"예: 180,000km, 개선 후 연비 6(배출 60kg), 30kg 감소 → 개선 전 90kg → 연비 4","src":"기출 2024-38"},{"t":"예: 120,000km, 연비 6(배출 40kg), 25% 감소 → 30kg → 연비 8","src":"기출 2026-39"},{"t":"환경부담금 비교: 절감 배출량 × 부담금 계수 ≥ 도입비용이 되는 최소 주행거리. 예: 주행거리 d km에서 절감 배출 0.0002d kg × 50만원 = 100d원 ≥ 1,500만원 → d ≥ 150,000km","src":"기출 2025-40"}]}],"함정":[{"x":"사용이 완료된 일회용 소모성 자재는 회수물류의 대상이다.","o":"일회용 소모성 자재는 폐기물류 대상.","src":"기출 2025-1"},{"x":"수배송 공동화 등 공동 물류활동의 확산은 환경오염을 촉진한다.","o":"환경오염을 줄인다.","src":"기출 2025-38"},{"x":"ISO 9000 시리즈는 환경경영을 기본방침으로 한다.","o":"환경경영은 ISO 14000 시리즈. ISO 9000은 품질경영.","src":"기출 2024-39, 보충"},{"x":"대상제품의 재고파악 및 가시성 확보가 용이하다. (역물류)","o":"역물류는 재고파악·가시성 확보가 어렵다.","src":"기출 2022-33"}]},"#19":{"묶음":[{"머리":"정의","줄":[{"t":"물류보안: 공항·항만과 물류시설에 폭발물·무기류 등 위해물품을 은닉·반입하는 행위 및 물류 시설·장비·인력·조직·정보망·화물 등에 위해를 가할 목적의 불법행위를 사전에 방지하기 위한 조치","src":"물류정책기본법 제2조 제1항 제13호"}]},{"머리":"제도별 내용","줄":[{"t":"C-TPAT: 2002년 미국 세관이 도입한 민관협력 프로그램. 수입업자·선사·운송회사·관세사 등 공급사슬 당사자 대상. 미국 세관의 보안기준 충족 시 통관절차 간소화","src":"기출 2021-38, 2022-40"},{"t":"CSI(컨테이너 보안구상): 미국 세관(CBP)이 미국 외부 주요 항만에 세관원을 파견해 위험도 높은 컨테이너를 사전 검사","src":"기출 2024-37"},{"t":"ISPS code: 해상화물 운송선박·항만시설의 해상테러 가능성 대비. 국제해사기구(IMO) 제정","src":"기출 2024-37"},{"t":"ISO 28000: 보안관리시스템 구축·인증 시 보안 자격을 인정하는 국제인증제도(국제표준화기구). 보안경영 인증제도","src":"기출 2022-40, 2024-37"},{"t":"AEO: 세계관세기구(WCO) 기준에 따라 물류기업이 일정 수준 이상 기준 충족 시 통관절차 간소화","src":"기출 2022-40"},{"t":"SAFE Port Act(SPA, 항만보안법 2006): CSI·SFI·C-TPAT 등의 법적 근거 부여","src":"기출 2024-37, 2023-33"},{"t":"ISF(Importer Security Filing, 10+2 rule): 항만보안법으로 법제화. 적재 24시간 전 미국 세관에 온라인 신고 의무. 수입자 신고사항 10가지, 운송사 신고사항 2가지","src":"기출 2023-33"},{"t":"CIP(Container Inspection Program): 수입 위험물 컨테이너가 국제해상 위험물 규칙(IMDG Code)을 지키는지 점검하는 제도","src":"기출 2025-37"}]}],"함정":[{"x":"국제표준화기구의 보안경영 인증: ISO 6780","o":"ISO 28000.","src":"기출 2022-40"}]}};
